CREATE TABLE `action` (
  `id` int NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the action was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the action was updated',
  `type` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of action',
  `model_id` int DEFAULT NULL,
  `name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'The description of the action',
  `parameters` longtext COLLATE utf8mb4_unicode_ci COMMENT 'The saved parameters for this action',
  `parameter_mappings` longtext COLLATE utf8mb4_unicode_ci COMMENT 'The saved parameter mappings for this action',
  `visualization_settings` longtext COLLATE utf8mb4_unicode_ci COMMENT 'The UI visualization_settings for this action',
  `public_uuid` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `made_public_by_id` int DEFAULT NULL COMMENT 'The ID of the User who first publically shared this Action.',
  `creator_id` int DEFAULT NULL COMMENT 'The user who created the action',
  `archived` bit(1) NOT NULL DEFAULT b'0',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `public_uuid_prefix` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Plaintext leading characters of public_uuid, used as an indexed narrowing key for public-link lookups.',
  `collection_id` int DEFAULT NULL COMMENT 'The Collection this Action is in; the model''s Collection when the Action has a model',
  `archived_directly` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the Action was archived directly, rather than along with its model or collection',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  UNIQUE KEY `public_uuid` (`public_uuid`),
  KEY `idx_action_public_uuid` (`public_uuid`),
  KEY `fk_action_made_public_by_id` (`made_public_by_id`),
  KEY `idx_action_creator_id` (`creator_id`),
  KEY `fk_action_model_id` (`model_id`),
  KEY `idx_action_public_uuid_prefix` (`public_uuid_prefix`),
  KEY `idx_action_collection_id` (`collection_id`),
  CONSTRAINT `fk_action_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_action_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`),
  CONSTRAINT `fk_action_made_public_by_id` FOREIGN KEY (`made_public_by_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_action_model_id` FOREIGN KEY (`model_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='An action is something you can do, such as run a readwrite query';
--;;
CREATE TABLE `agent_api_call_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Autoincrement primary key',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the Agent API call was made',
  `user_id` int DEFAULT NULL COMMENT 'Metabase user behind the call; NULL for unauthenticated calls. Non-PII, always recorded.',
  `tenant_id` int DEFAULT NULL COMMENT 'Snapshot of the calling user''s tenant at call time; NULL for non-tenant users. Non-PII.',
  `client_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Canonical client key classified from the User-Agent (metabase-cli/other). Self-reported, analytics-only, never gated on. Non-PII.',
  `operation` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'HTTP method + request URI of the Agent API call, e.g. "POST /api/agent/v1/query".',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Outcome of the call, success or error (derived from the HTTP status code).',
  `duration_ms` int DEFAULT NULL COMMENT 'Wall-clock duration of the call in milliseconds',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client IP captured at call time, PII (gated by analytics-pii-retention-enabled).',
  `error_message` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Error message for a failed call, PII (gated by analytics-pii-retention-enabled, truncated); NULL on success or when gating is off.',
  PRIMARY KEY (`id`),
  KEY `idx_agent_api_call_log_user_id` (`user_id`),
  KEY `idx_agent_api_call_log_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One row per direct Agent API HTTP call; client identity + PII captured on the row so the view needs no session join (modeled on mcp_tool_call_log)';
--;;
CREATE TABLE `ai_usage_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the LLM call was made',
  `source` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Origin of the LLM call, e.g. agent, slackbot, document-gen, intent-classification, example-question-gen, oss-sql-gen, semantic-search-embedding',
  `model` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Full model identifier, e.g. anthropic/claude-sonnet-4-20250514',
  `prompt_tokens` int NOT NULL COMMENT 'Number of input/prompt tokens',
  `completion_tokens` int NOT NULL COMMENT 'Number of output/completion tokens',
  `total_tokens` int NOT NULL COMMENT 'Sum of prompt_tokens + completion_tokens',
  `user_id` int DEFAULT NULL COMMENT 'Metabase user who triggered the call. NULL for system/background calls.',
  `tenant_id` int DEFAULT NULL COMMENT 'Snapshot of user tenant at request time. NULL for non-tenant users.',
  `conversation_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Reference to metabot_conversation. NULL for non-conversational calls.',
  `profile_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AI profile used, e.g. nlq, sql, slackbot',
  `request_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'UUID for correlating with Snowplow events',
  `ai_proxied` bit(1) DEFAULT NULL COMMENT 'Whether this call was routed through the Metabase Cloud AI proxy (true) or directly via BYOK keys (false). Null for rows created before this migration.',
  `cache_creation_tokens` int DEFAULT NULL COMMENT 'Number of input tokens written to the provider prompt cache (Anthropic cache_creation_input_tokens).',
  `cache_read_tokens` int DEFAULT NULL COMMENT 'Number of input tokens served from the provider prompt cache (Anthropic cache_read_input_tokens).',
  `provider` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Provider type that served the call, e.g. openrouter. A managed-proxy call records the wire family it was served as, so it reads anthropic and is told apart by ai_proxied',
  `model_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Model as the provider names it, without the connection key, e.g. anthropic/claude-haiku-4.5',
  PRIMARY KEY (`id`),
  KEY `idx_ai_usage_log_user_id` (`user_id`),
  KEY `idx_ai_usage_log_conversation_id` (`conversation_id`),
  KEY `idx_ai_usage_log_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Universal ledger for all LLM API call usage tracking';
--;;
CREATE TABLE `analysis_finding` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `entity_type` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_id` int NOT NULL,
  `analyzed_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the analysis was performed',
  `result` bit(1) NOT NULL COMMENT 'The result of the analysis - true for passed, false for failed',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_analysis_finding` (`entity_type`,`entity_id`),
  KEY `idx_analyzed_entity` (`entity_type`,`entity_id`),
  KEY `idx_analysis_result` (`result`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Findings from analysis of cards, transforms, dashboards, etc.';
--;;
CREATE TABLE `analysis_finding_error` (
  `id` int NOT NULL AUTO_INCREMENT,
  `analyzed_entity_type` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The type of the analyzed entity (card, transform, segment, etc.)',
  `analyzed_entity_id` int NOT NULL COMMENT 'The ID of the analyzed entity',
  `error_type` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The type of error (missing-column, missing-table-alias, duplicate-column, syntax-error, validation-exception-error)',
  `error_detail` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Additional error details (e.g., column name, alias name, error message)',
  `source_entity_type` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The type of the source entity causing the error (table, card, etc.)',
  `source_entity_id` int DEFAULT NULL COMMENT 'The ID of the source entity causing the error',
  PRIMARY KEY (`id`),
  KEY `idx_analysis_finding_error_source` (`source_entity_type`,`source_entity_id`),
  KEY `idx_analysis_finding_error_analyzed` (`analyzed_entity_type`,`analyzed_entity_id`),
  KEY `idx_analysis_finding_error_type` (`error_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Individual validation errors from analysis with source entity information';
--;;
CREATE TABLE `analysis_finding_status` (
  `id` int NOT NULL AUTO_INCREMENT,
  `entity_type` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The type of the entity',
  `entity_id` int NOT NULL COMMENT 'The ID of the entity',
  `stale` int NOT NULL DEFAULT '0' COMMENT 'How many writes changed what the job reads for the entity since the job last read it; the job processes it while above 0',
  `fail_count` int NOT NULL DEFAULT '0' COMMENT 'How many times in a row the job failed to process the entity since a write changed it',
  `terminal` bit(1) NOT NULL DEFAULT b'0' COMMENT 'True when the job gave up on the entity after its failures, until a write changes it',
  `analysis_version` int NOT NULL COMMENT 'The version of the analysis that last processed the entity',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_analysis_finding_status` (`entity_type`,`entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Whether each analyzable entity is to be analyzed again';
--;;
CREATE TABLE `api_key` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'The ID of the API Key itself',
  `user_id` int DEFAULT NULL,
  `key` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The hashed API key',
  `key_prefix` varchar(7) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The first 7 characters of the unhashed key',
  `creator_id` int DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp when the key was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp when the key was last updated',
  `name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The user-defined name of the API key.',
  `updated_by_id` int NOT NULL COMMENT 'The ID of the user that last updated this API key',
  `scope` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The scope of the API key, if applicable',
  `last_used_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When this API key was last used to authenticate a request; NULL until first use. Updated in place (throttled), not per request.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `key_prefix` (`key_prefix`),
  UNIQUE KEY `name` (`name`),
  KEY `idx_api_key_created_by` (`creator_id`),
  KEY `idx_api_key_user_id` (`user_id`),
  KEY `idx_api_key_updated_by_id` (`updated_by_id`),
  CONSTRAINT `fk_api_key_created_by_user_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`),
  CONSTRAINT `fk_api_key_updated_by_id_user_id` FOREIGN KEY (`updated_by_id`) REFERENCES `core_user` (`id`),
  CONSTRAINT `fk_api_key_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='An API Key';
--;;
CREATE TABLE `api_key_usage_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Autoincrement primary key',
  `api_key_id` int NOT NULL COMMENT 'The API key that authenticated the request. Deliberately not a foreign key so deleting a key does not cascade away its usage history.',
  `user_id` int DEFAULT NULL COMMENT 'The API key''s own synthetic service-account user, resolved at request time; NULL when the key has no user. Used for permission checks, not a real person. Not a foreign key, for the same reason as api_key_id. Non-PII.',
  `created_by_id` int DEFAULT NULL COMMENT 'The real human who created the API key, resolved from the same auth query as user_id; NULL when the key has no user. Not a foreign key, for the same reason as api_key_id. Non-PII.',
  `route_template` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Reconstructed route template of the request, e.g. /api/card/:id. Never the raw URI or query string. Non-PII.',
  `http_method` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'HTTP method of the request, e.g. GET or POST. Non-PII.',
  `status` int NOT NULL COMMENT 'HTTP status code of the response. Non-PII. Streamed responses (for example query results) always store 202, because the real status is only known after the stream ends, so do not read 202 as an outcome.',
  `duration_ms` int NOT NULL COMMENT 'Wall-clock duration of the request in milliseconds',
  `occurred_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the request happened, captured on the request thread. The default is a fallback only — the recorder always sets this explicitly, since the row itself may not land in the table until a scheduled flush later.',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client IP captured at request time, PII (gated by analytics-pii-retention-enabled).',
  `user_agent` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Raw User-Agent header captured at request time, PII (gated by analytics-pii-retention-enabled).',
  `client_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Caller classified from the raw User-Agent (metabase-cli, curl, postman, python-requests, r, node, or other). Non-PII, always recorded — distinct from the raw, PII-gated user_agent column.',
  `embedding_client` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Raw X-Metabase-Client header value, when present. Non-PII, same status as view_log/query_execution.embedding_client. Supplementary to client_name (the primary classification axis) — almost never set on API-key traffic, since the SDK/embed.js clients that send it authenticate via JWT/SSO, not API keys.',
  `embedding_hostname` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Hostname parsed from the embed referrer header, when present. Non-PII, same status as view_log/query_execution/metabot_conversation.embedding_hostname. Only meaningful alongside embedding_client.',
  PRIMARY KEY (`id`),
  KEY `idx_api_key_usage_log_api_key_id` (`api_key_id`),
  KEY `idx_api_key_usage_log_created_by_id` (`created_by_id`),
  KEY `idx_api_key_usage_log_occurred_at` (`occurred_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One row per API-key-authenticated request; user and key creator denormalized on so the view needs no api_key join (modeled on agent_api_call_log)';
--;;
CREATE TABLE `application_permissions_revision` (
  `id` int NOT NULL AUTO_INCREMENT,
  `before` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Serialized JSON of the permission graph before the changes.',
  `after` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Serialized JSON of the changes in permission graph.',
  `user_id` int NOT NULL COMMENT 'The ID of the admin who made this set of changes.',
  `created_at` timestamp(6) NOT NULL,
  `remark` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Optional remarks explaining why these changes were made.',
  PRIMARY KEY (`id`),
  KEY `fk_general_permissions_revision_user_id` (`user_id`),
  CONSTRAINT `fk_general_permissions_revision_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Used to keep track of changes made to general permissions.';
--;;
CREATE TABLE `audit_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `topic` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The topic of a given audit event',
  `timestamp` timestamp(6) NOT NULL COMMENT 'The time an event was recorded',
  `end_timestamp` timestamp(6) NULL DEFAULT NULL COMMENT 'The time an event ended, if applicable',
  `user_id` int DEFAULT NULL COMMENT 'The user who performed an action or triggered an event',
  `model` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The name of the model this event applies to (e.g. Card, Dashboard), if applicable',
  `model_id` int DEFAULT NULL COMMENT 'The ID of the model this event applies to, if applicable',
  `details` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'A JSON map with metadata about the event',
  PRIMARY KEY (`id`),
  KEY `idx_audit_log_model_model_id` (`model`,`model_id`),
  KEY `idx_audit_log_entity_qualified_id` (((case when (`model` = _utf8mb4'Dataset') then concat(_utf8mb4'card_',`model_id`) when (`model_id` is null) then NULL else concat(lower(`model`),_utf8mb4'_',`model_id`) end)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Used to store application events for auditing use cases';
--;;
CREATE TABLE `auth_identity` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Integer primary key',
  `user_id` int NOT NULL COMMENT 'Foreign key to core_user',
  `provider` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Authentication provider type (password, google, ldap, saml, jwt, support)',
  `credentials` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON object containing provider-specific credentials',
  `metadata` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON object containing provider-specific metadata',
  `provider_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Provider-specific identifier (email for password/Google, DN for LDAP, subject for SAML/JWT)',
  `last_used_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Timestamp of last successful authentication',
  `expires_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Timestamp when this authentication method expires (null = never expires)',
  `created_at` timestamp(6) NOT NULL COMMENT 'Timestamp when this identity was created',
  `updated_at` timestamp(6) NOT NULL COMMENT 'Timestamp when this identity was last updated',
  `confirmed_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When this identity was confirmed (e.g. MFA enrollment completed). Null = unconfirmed.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_auth_identity_user_provider` (`user_id`,`provider`),
  KEY `idx_auth_identity_user_id` (`user_id`),
  KEY `idx_auth_identity_provider` (`provider`),
  KEY `idx_auth_identity_provider_id` (`provider_id`),
  KEY `idx_auth_identity_provider_provider_id` (`provider`,`provider_id`),
  CONSTRAINT `fk_auth_identity_core_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores authentication credentials for users. A user can have multiple auth identities.';
--;;
CREATE TABLE `bookmark_ordering` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT 'ID of the User who ordered bookmarks',
  `type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'type of the Bookmark',
  `item_id` int NOT NULL COMMENT 'id of the item being bookmarked (Card, Collection, Dashboard, ...) no FK, so may no longer exist',
  `ordering` int NOT NULL COMMENT 'order of bookmark for user',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_bookmark_user_id_type_item_id` (`user_id`,`type`,`item_id`),
  UNIQUE KEY `unique_bookmark_user_id_ordering` (`user_id`,`ordering`),
  KEY `idx_bookmark_ordering_user_id` (`user_id`),
  CONSTRAINT `fk_bookmark_ordering_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table holding ordering information for various bookmark tables';
--;;
CREATE TABLE `cache_config` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `model` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of an entity model',
  `model_id` int NOT NULL COMMENT 'ID of the said entity',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp when the config was inserted',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp when the config was updated',
  `strategy` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'caching strategy name',
  `config` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'caching strategy configuration',
  `state` longtext COLLATE utf8mb4_unicode_ci COMMENT 'state for strategies needing to keep some data between runs',
  `invalidated_at` timestamp(6) NULL DEFAULT NULL COMMENT 'indicates when a cache was invalidated last time for schedule-based strategies',
  `next_run_at` timestamp(6) NULL DEFAULT NULL COMMENT 'keeps next time to run for schedule-based strategies',
  `refresh_automatically` bit(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_cache_config_unique_model` (`model`,`model_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Cache Configuration';
--;;
CREATE TABLE `card_bookmark` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT 'ID of the User who bookmarked the Card',
  `card_id` int NOT NULL COMMENT 'ID of the Card bookmarked by the user',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the bookmark was created',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_card_bookmark_user_id_card_id` (`user_id`,`card_id`),
  KEY `idx_card_bookmark_user_id` (`user_id`),
  KEY `idx_card_bookmark_card_id` (`card_id`),
  CONSTRAINT `fk_card_bookmark_dashboard_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_card_bookmark_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table holding bookmarks on cards';
--;;
CREATE TABLE `card_label` (
  `id` int NOT NULL AUTO_INCREMENT,
  `card_id` int NOT NULL,
  `label_id` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_card_label_card_id_label_id` (`card_id`,`label_id`),
  KEY `idx_card_label_card_id` (`card_id`),
  KEY `idx_card_label_label_id` (`label_id`),
  CONSTRAINT `fk_card_label_ref_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_card_label_ref_label_id` FOREIGN KEY (`label_id`) REFERENCES `label` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `channel` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'channel name',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'channel description',
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Channel type',
  `details` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Channel details, used to store authentication information or channel-specific settings',
  `active` bit(1) NOT NULL DEFAULT b'1' COMMENT 'whether the channel is active',
  `created_at` timestamp(6) NOT NULL COMMENT 'Timestamp when the channel was inserted',
  `updated_at` timestamp(6) NOT NULL COMMENT 'Timestamp when the channel was updated',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Channel configurations';
--;;
CREATE TABLE `channel_template` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'the name of the template',
  `channel_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'the channel type of the template',
  `details` longtext COLLATE utf8mb4_unicode_ci COMMENT 'the details of the template',
  `created_at` timestamp(6) NOT NULL COMMENT 'The timestamp of when the template was created',
  `updated_at` timestamp(6) NOT NULL COMMENT 'The timestamp of when the template was last updated',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='custom template for the channel';
--;;
CREATE TABLE `cloud_migration` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `external_id` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Matching ID in Cloud for this migration',
  `upload_url` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'URL where the backup will be uploaded to',
  `state` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'init' COMMENT 'Current state of the migration: init, setup, dump, upload, done, error, cancelled',
  `progress` int NOT NULL DEFAULT '0' COMMENT 'Number between 0 to 100 representing progress as a percentage',
  `created_at` timestamp(6) NOT NULL COMMENT 'Timestamp when the config was inserted',
  `updated_at` timestamp(6) NOT NULL COMMENT 'Timestamp when the config was updated',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Migrate to cloud directly from Metabase';
--;;
CREATE TABLE `collection` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `archived` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether this Collection has been archived and should be hidden from users.',
  `location` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '/' COMMENT 'Directory-structure path of ancestor Collections. e.g. "/1/2/" means our Parent is Collection 2, and their parent is Collection 1.',
  `personal_owner_id` int DEFAULT NULL COMMENT 'If set, this Collection is a personal Collection, for exclusive use of the User with this ID.',
  `slug` varchar(510) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `namespace` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The namespace (hierachy) this Collection belongs to. NULL means the Collection is in the default namespace.',
  `authority_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nullable column to incidate collection''s authority level. Initially values are "official" and nil.',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp of when this Collection was created.',
  `type` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'This is used to differentiate instance-analytics collections from all other collections.',
  `is_sample` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Is the collection part of the sample content?',
  `archive_operation_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The UUID of the trash operation. Each time you trash a collection subtree, you get a unique ID.',
  `archived_directly` bit(1) DEFAULT NULL COMMENT 'Whether the item was trashed independently or as a subcollection',
  `is_remote_synced` bit(1) DEFAULT b'0' COMMENT 'Indicates if this collection is synced from a remote source',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  UNIQUE KEY `unique_collection_personal_owner_id` (`personal_owner_id`),
  KEY `idx_collection_location` (`location`),
  KEY `idx_collection_personal_owner_id` (`personal_owner_id`),
  KEY `idx_collection_type` (`type`),
  CONSTRAINT `fk_collection_personal_owner_id` FOREIGN KEY (`personal_owner_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Collections are an optional way to organize Cards and handle permissions for them.';
--;;
INSERT INTO `collection` (`id`, `name`, `description`, `archived`, `location`, `personal_owner_id`, `slug`, `namespace`, `authority_level`, `entity_id`, `created_at`, `type`, `is_sample`, `archive_operation_id`, `archived_directly`, `is_remote_synced`) VALUES (1,'Trash',NULL,_binary '\0','/',NULL,'trash',NULL,NULL,'trashtrashtrashtrasht','2026-11-03 11:45:09.960759','trash',_binary '\0',NULL,NULL,_binary '\0');
--;;
CREATE TABLE `collection_bookmark` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT 'ID of the User who bookmarked the Collection',
  `collection_id` int NOT NULL COMMENT 'ID of the Card bookmarked by the user',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the bookmark was created',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_collection_bookmark_user_id_collection_id` (`user_id`,`collection_id`),
  KEY `idx_collection_bookmark_user_id` (`user_id`),
  KEY `idx_collection_bookmark_collection_id` (`collection_id`),
  CONSTRAINT `fk_collection_bookmark_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_collection_bookmark_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table holding bookmarks on collections';
--;;
CREATE TABLE `collection_permission_graph_revision` (
  `id` int NOT NULL AUTO_INCREMENT,
  `before` longtext COLLATE utf8mb4_unicode_ci,
  `after` longtext COLLATE utf8mb4_unicode_ci,
  `user_id` int NOT NULL COMMENT 'The ID of the admin who made this set of changes.',
  `created_at` timestamp(6) NOT NULL,
  `remark` longtext COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `fk_collection_revision_user_id` (`user_id`),
  CONSTRAINT `fk_collection_revision_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Used to keep track of changes made to collections.';
--;;
CREATE TABLE `comment` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key for comment table',
  `parent_comment_id` int DEFAULT NULL COMMENT 'ID of the parent comment for threading (null for root comments)',
  `target_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'document' COMMENT 'Type of entity being commented on',
  `target_id` int NOT NULL COMMENT 'ID of the entity being commented on',
  `child_target_id` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Sub-entity ID (e.g., document block node ID)',
  `creator_id` int NOT NULL COMMENT 'User who created this comment',
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The comment content',
  `is_resolved` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether this comment thread is resolved',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp when comment was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp when comment was last updated',
  `deleted_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Soft delete timestamp (null if not deleted)',
  `content_html` longtext COLLATE utf8mb4_unicode_ci COMMENT 'HTML-rendered version of the comment content',
  `context` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Optional context metadata about the comment (e.g., active timeline for exploration comments)',
  PRIMARY KEY (`id`),
  KEY `idx_comment_entity` (`target_type`,`target_id`),
  KEY `idx_comment_creator_id` (`creator_id`),
  KEY `idx_comment_parent_comment_id` (`parent_comment_id`),
  CONSTRAINT `fk_comment_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_comment_parent_comment_id` FOREIGN KEY (`parent_comment_id`) REFERENCES `comment` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Comments on various entities (documents, dashboards, etc.)';
--;;
CREATE TABLE `comment_reaction` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key for comment_reaction table',
  `comment_id` int NOT NULL COMMENT 'ID of the comment being reacted to',
  `user_id` int NOT NULL COMMENT 'User who added this reaction',
  `emoji` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp when reaction was added',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_comment_emoji` (`comment_id`,`user_id`,`emoji`),
  KEY `fk_comment_reaction_user_id` (`user_id`),
  KEY `idx_comment_reaction_comment_id` (`comment_id`),
  CONSTRAINT `fk_comment_reaction_comment_id` FOREIGN KEY (`comment_id`) REFERENCES `comment` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_comment_reaction_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Store reactions (emojis) on comments';
--;;
CREATE TABLE `connection_impersonations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `db_id` int NOT NULL COMMENT 'ID of the database this connection impersonation policy affects',
  `group_id` int NOT NULL COMMENT 'ID of the permissions group this connection impersonation policy affects',
  `attribute` longtext COLLATE utf8mb4_unicode_ci COMMENT 'User attribute associated with the database role to use for this connection impersonation policy',
  PRIMARY KEY (`id`),
  UNIQUE KEY `conn_impersonation_unique_group_id_db_id` (`group_id`,`db_id`),
  KEY `idx_conn_impersonations_db_id` (`db_id`),
  KEY `idx_conn_impersonations_group_id` (`group_id`),
  CONSTRAINT `fk_conn_impersonation_db_id` FOREIGN KEY (`db_id`) REFERENCES `metabase_database` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_conn_impersonation_group_id` FOREIGN KEY (`group_id`) REFERENCES `permissions_group` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table for holding connection impersonation policies';
--;;
CREATE TABLE `content_diagnostics_finding` (
  `id` int NOT NULL AUTO_INCREMENT,
  `scan_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Groups all rows from one scan run (UUID). API serves the newest scan.',
  `entity_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Polymorphic — card/dashboard/document/collection/transform. No FK.',
  `entity_id` int NOT NULL COMMENT 'Polymorphic id of the flagged entity (no FK; paired with entity_type).',
  `finding_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'stale/duplicated/empty/crowded/sparse/slow/trash-not-emptied',
  `scope_collection_id` int DEFAULT NULL COMMENT 'collection the entity lived in at scan time (filter/sort); no FK',
  `details` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON evidence — e.g. {threshold_days, last_active_at}',
  `detected_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When this finding was detected (per-finding freshness signal).',
  `invalidated_at` timestamp(6) NULL DEFAULT NULL COMMENT 'stamped when invalidated/superseded; null = active (drives the served-set filter)',
  `last_active_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Entity''s last activity at scan time (card last_used_at / dashboard last_viewed_at); null = never used/ran. Frozen verdict evidence; powers the threshold-days serve filter.',
  `entity_name` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Entity''s name at scan time; served as entity_display_name and used as the sort/search key. text because upstream names are unbounded.',
  `entity_created_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Entity''s created_at (immutable). Denormalized for sort + display.',
  `entity_creator_id` int DEFAULT NULL COMMENT 'Entity''s creator_id at scan time; no FK (polymorphic, mirrors entity_id). Sort key (groups by creator).',
  `entity_creator_name` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Creator''s common_name at scan time (resolved from creator_id). Sort key for created-by, served in details.creator. text because common_name can be an email, which is unbounded on Postgres.',
  `duration_ms` bigint DEFAULT NULL COMMENT 'Verdict magnitude for slow findings - median query ms (card) / last-run ms (transform) / slowest-child ms (dashboard/document roll-up); null on all other finding types (per-type named magnitude column). bigint, not int - a pathological run duration can exceed 2^31-1 ms.',
  `content_count` bigint DEFAULT NULL COMMENT 'Verdict magnitude for imbalanced (empty/sparse/crowded) findings - items (collection) / dashcards or tabs (dashboard) / cards (document) / rows (card, transform); 0 on every empty finding, null on all other finding types (per-type named magnitude column). bigint - house choice for magnitude columns.',
  `duplicate_count` bigint DEFAULT NULL COMMENT 'Verdict magnitude for duplicated findings - the number of other same-type entities sharing the normalized name (cluster size minus 1); null on all other finding types (per-type named magnitude column).',
  `card_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'report_card.type (question/model/metric) at scan time, card findings only; null on all other entity types. Denormalized filter key for the card sub-kind values of the entity-types param (mutable upstream - drift until the next scan, like entity_name).',
  `entity_collection_name` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Scan-time name of the scope_collection_id collection (root rows store the root label); sort/display value for the collection column.',
  `entity_kind` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Flat entity kind at scan time - card_type for cards, else entity_type; serves the entity-types filter and entity-type sort.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_uniq_cd_finding` (`scan_id`,`entity_type`,`entity_id`,`finding_type`),
  KEY `idx_cd_finding_entity` (`entity_type`,`entity_id`),
  KEY `idx_cd_finding_detected` (`detected_at`),
  KEY `idx_cd_finding_ftype_created` (`finding_type`,`entity_created_at`),
  KEY `idx_cd_finding_ftype_active` (`finding_type`,`last_active_at`),
  KEY `idx_cd_finding_ftype_duration` (`finding_type`,`duration_ms`),
  KEY `idx_cd_finding_ftype_content_count` (`finding_type`,`content_count`),
  KEY `idx_cd_finding_ftype_duplicate_count` (`finding_type`,`duplicate_count`),
  KEY `idx_cd_finding_ftype_entity_kind` (`finding_type`,`entity_kind`),
  KEY `idx_cd_finding_invalidated` (`invalidated_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One detected problem for one entity, from one scan run.';
--;;
CREATE TABLE `content_translation` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `locale` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Locale',
  `msgid` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The raw string',
  `msgstr` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The translation',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Content translations';
--;;
CREATE TABLE `core_session` (
  `id` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` int NOT NULL,
  `created_at` timestamp(6) NOT NULL,
  `anti_csrf_token` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `key_hashed` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `auth_identity_id` int DEFAULT NULL COMMENT 'Foreign key to auth_identity - tracks which auth method was used for login',
  `expires_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Timestamp when this session expires (from auth_identity or calculated)',
  `last_active_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Tracks when the session was last used, for inactivity timeout enforcement',
  `saml_session_index` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SessionIndex from the SAML login assertion, sent back in the SLO LogoutRequest to identify this session. NULL for non-SAML sessions and for sessions created before this column existed.',
  `saml_name_id` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'NameID from the SAML login assertion. Sent back in the SLO LogoutRequest, since the IdP identifies the subject by this and not by email. NULL for non-SAML sessions.',
  `saml_name_id_format` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Format attribute of the SAML NameID. Echoed back in the LogoutRequest because some IdPs compare it literally. NULL when the IdP sent none.',
  `mfa_auth_identity_id` int DEFAULT NULL COMMENT 'Foreign key to auth_identity method used for MFA',
  `ended_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When the session ended (revoked, expired, timed out, or its user or tenant deactivated); null while live',
  `end_reason` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Why the session ended, e.g. admin, logout, password-change, expired; null while live',
  `ended_by_user_id` int DEFAULT NULL COMMENT 'The user who ended the session, when a person did',
  PRIMARY KEY (`id`),
  KEY `fk_session_ref_user_id` (`user_id`),
  KEY `idx_core_session_key_hashed` (`key_hashed`),
  KEY `idx_core_session_auth_identity_id` (`auth_identity_id`),
  KEY `fk_core_session_ended_by_user_id` (`ended_by_user_id`),
  CONSTRAINT `fk_core_session_ended_by_user_id` FOREIGN KEY (`ended_by_user_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_session_auth_identity` FOREIGN KEY (`auth_identity_id`) REFERENCES `auth_identity` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_session_ref_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `core_user` (
  `id` int NOT NULL AUTO_INCREMENT,
  `email` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `first_name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `password` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `password_salt` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_joined` timestamp(6) NOT NULL,
  `last_login` timestamp(6) NULL DEFAULT NULL,
  `is_superuser` bit(1) NOT NULL DEFAULT b'0',
  `is_active` bit(1) NOT NULL DEFAULT b'1',
  `reset_token` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reset_triggered` bigint DEFAULT NULL,
  `is_qbnewb` bit(1) NOT NULL DEFAULT b'1',
  `login_attributes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `sso_source` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'String to indicate the SSO backend the user is from',
  `locale` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Preferred ISO locale (language/country) code, e.g "en" or "en-US", for this User. Overrides site default.',
  `is_datasetnewb` bit(1) NOT NULL DEFAULT b'1',
  `settings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Serialized JSON containing User-local Settings for this User',
  `type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'personal' COMMENT 'The type of user',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `deactivated_at` timestamp(6) NULL DEFAULT NULL COMMENT 'The timestamp at which a user was deactivated',
  `tenant_id` int DEFAULT NULL COMMENT 'The ID of the tenant for this user',
  `jwt_attributes` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON object containing attributes set through jwt',
  `deactivated_with_tenant` bit(1) DEFAULT NULL COMMENT 'if this user and its tenant are both deactivated, represents whether the user was deactivated\n*with* the tenant (in which case it should be reactivated when the tenant is reactivated)\nor was deactivated independently.',
  `is_data_analyst` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Indicates if the user has data analyst privileges for Data Studio',
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_core_user_tenant_id` (`tenant_id`),
  KEY `idx_user_full_name` ((concat(`first_name`,_utf8mb4' ',`last_name`))),
  CONSTRAINT `fk_core_user_tenant_id` FOREIGN KEY (`tenant_id`) REFERENCES `tenant` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=13371339 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
INSERT INTO `core_user` (`id`, `email`, `first_name`, `last_name`, `password`, `password_salt`, `date_joined`, `last_login`, `is_superuser`, `is_active`, `reset_token`, `reset_triggered`, `is_qbnewb`, `login_attributes`, `updated_at`, `sso_source`, `locale`, `is_datasetnewb`, `settings`, `type`, `entity_id`, `deactivated_at`, `tenant_id`, `jwt_attributes`, `deactivated_with_tenant`, `is_data_analyst`) VALUES (13371338,'internal@metabase.com','Metabase','Internal',NULL,NULL,'2026-11-03 11:45:09.000000',NULL,_binary '\0',_binary '\0',NULL,NULL,_binary '',NULL,NULL,NULL,NULL,_binary '',NULL,'internal','126affbbd77c11f1af7ef',NULL,NULL,NULL,NULL,_binary '\0');
