CREATE TABLE `custom_viz_plugin` (
  `id` int NOT NULL AUTO_INCREMENT,
  `identifier` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Unique identifier used as visualization display type. Comes from the manifest "name" field.',
  `display_name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Human-readable name from the plugin manifest',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Plugin status - active or error',
  `error_message` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Last error message if status is error',
  `bundle` longblob,
  `bundle_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SHA-256 hex of the uploaded bundle, used as the on-disk cache key and HTTP ETag. Null for dev-only plugins.',
  `created_at` timestamp(6) NOT NULL COMMENT 'Timestamp when the plugin was registered',
  `updated_at` timestamp(6) NOT NULL COMMENT 'Timestamp when the plugin was last updated',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT 'Whether the plugin is enabled for use in dashboards and questions',
  `icon` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Icon from plugin manifest - asset path resolved to a URL',
  `manifest` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON manifest from metabase-plugin.json in the uploaded bundle',
  `metabase_version` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Metabase version range requirement from manifest (e.g. ">=1.59 <1.62")',
  `dev_bundle_url` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Dev server URL for hot-reload development (e.g. http://localhost:5174)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `identifier` (`identifier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores registered custom visualization plugins uploaded as zip bundles';
--;;
CREATE TABLE `dashboard_bookmark` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT 'ID of the User who bookmarked the Dashboard',
  `dashboard_id` int NOT NULL COMMENT 'ID of the Dashboard bookmarked by the user',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the bookmark was created',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_dashboard_bookmark_user_id_dashboard_id` (`user_id`,`dashboard_id`),
  KEY `idx_dashboard_bookmark_user_id` (`user_id`),
  KEY `idx_dashboard_bookmark_dashboard_id` (`dashboard_id`),
  CONSTRAINT `fk_dashboard_bookmark_dashboard_id` FOREIGN KEY (`dashboard_id`) REFERENCES `report_dashboard` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_dashboard_bookmark_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table holding bookmarks on dashboards';
--;;
CREATE TABLE `dashboard_favorite` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT 'ID of the User who favorited the Dashboard.',
  `dashboard_id` int NOT NULL COMMENT 'ID of the Dashboard favorited by the User.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_dashboard_favorite_user_id_dashboard_id` (`user_id`,`dashboard_id`),
  KEY `idx_dashboard_favorite_user_id` (`user_id`),
  KEY `idx_dashboard_favorite_dashboard_id` (`dashboard_id`),
  CONSTRAINT `fk_dashboard_favorite_dashboard_id` FOREIGN KEY (`dashboard_id`) REFERENCES `report_dashboard` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_dashboard_favorite_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Presence of a row here indicates a given User has favorited a given Dashboard.';
--;;
CREATE TABLE `dashboard_tab` (
  `id` int NOT NULL AUTO_INCREMENT,
  `dashboard_id` int NOT NULL COMMENT 'The dashboard that a tab is on',
  `name` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Displayed name of the tab',
  `position` int NOT NULL COMMENT 'Position of the tab with respect to others tabs in dashboard',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp at which the tab was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp at which the tab was last updated',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `fk_dashboard_tab_ref_dashboard_id` (`dashboard_id`),
  CONSTRAINT `fk_dashboard_tab_ref_dashboard_id` FOREIGN KEY (`dashboard_id`) REFERENCES `report_dashboard` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Join table connecting dashboard to dashboardcards';
--;;
CREATE TABLE `dashboardcard_series` (
  `id` int NOT NULL AUTO_INCREMENT,
  `dashboardcard_id` int NOT NULL,
  `card_id` int NOT NULL,
  `position` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_dashboardcard_series_dashboardcard_id` (`dashboardcard_id`),
  KEY `idx_dashboardcard_series_card_id` (`card_id`),
  CONSTRAINT `fk_dashboardcard_series_ref_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_dashboardcard_series_ref_dashboardcard_id` FOREIGN KEY (`dashboardcard_id`) REFERENCES `report_dashboardcard` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `data_app` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Slug, used in the URL /apps/:name',
  `display_name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Human-readable name from the manifest, shown in the admin UI',
  `allowed_hosts` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of origins the sandboxed bundle may fetch/XHR. NULL when none configured.',
  `bundle_path` varchar(1024) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Path within the repository to this app''s built bundle file',
  `bundle` longblob,
  `bundle_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SHA-256 hex of the cached bytes, used as HTTP ETag. NULL until first sync.',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT 'Admin toggle. When false the app is not served and is hidden from the data-app routes.',
  `created_at` timestamp(6) NOT NULL COMMENT 'Timestamp when the data app was first synced',
  `updated_at` timestamp(6) NOT NULL COMMENT 'Timestamp when the data app was last updated',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Optional one-line description from the manifest, shown in the admin UI. NULL when the app declares none.',
  `resource_collection_id` int DEFAULT NULL COMMENT 'Server-owned collection containing the data app''s generated saved questions',
  `version` int NOT NULL DEFAULT '1' COMMENT 'Data app contract version from the manifest. 1 when the app declares none.',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  UNIQUE KEY `uq_data_app_entity_id` (`entity_id`),
  UNIQUE KEY `uq_data_app_resource_collection_id` (`resource_collection_id`),
  KEY `idx_data_app_resource_collection_id` (`resource_collection_id`),
  CONSTRAINT `fk_data_app_resource_collection_id` FOREIGN KEY (`resource_collection_id`) REFERENCES `collection` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores Git-synced data-app bundles, one row per data_apps/<dir> app.';
--;;
CREATE TABLE `data_app_group_assignment` (
  `id` int NOT NULL AUTO_INCREMENT,
  `data_app_id` int NOT NULL COMMENT 'Data app receiving access through the assigned group',
  `permission_group_id` int NOT NULL COMMENT 'Permission group assigned to the data app',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_data_app_group_assignment` (`data_app_id`,`permission_group_id`),
  KEY `idx_data_app_group_assignment_group` (`permission_group_id`),
  CONSTRAINT `fk_data_app_group_assignment_app` FOREIGN KEY (`data_app_id`) REFERENCES `data_app` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_data_app_group_assignment_group` FOREIGN KEY (`permission_group_id`) REFERENCES `permissions_group` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Permission group assignments for data apps';
--;;
CREATE TABLE `data_complexity_score` (
  `id` int NOT NULL AUTO_INCREMENT,
  `fingerprint` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Fingerprint of the scoring inputs (formula version, synonym threshold, embedding model)',
  `score_data` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON-serialized complexity score response returned by the data-complexity-score endpoint',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When this score snapshot was computed and stored',
  `source` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'appdb' COMMENT 'Provenance — "appdb" for cron/API/CLI-from-appdb, or "representation:<digest>" for CLI runs that scored a representation directory.',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Append-only snapshots of the computed Data Complexity Score shown in the Metabot overview UI';
--;;
CREATE TABLE `data_edit_undo_chain` (
  `id` int NOT NULL AUTO_INCREMENT,
  `batch_num` int NOT NULL COMMENT 'Batch number for grouped changes (global increment)',
  `table_id` int NOT NULL COMMENT 'Reference to the table being modified',
  `row_pk` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PK of the row being modified, potentially composite. Stored as a sorted JSON map.',
  `user_id` int NOT NULL COMMENT 'ID of the user who made the change',
  `scope` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Identifies where the changes were made from',
  `undoable` bit(1) NOT NULL DEFAULT b'1' COMMENT 'Identifies whether a change can be undo',
  `raw_before` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Value of the field before the change',
  `raw_after` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Value of the field after the change',
  `undone` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether this change has been undone',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the change was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the change was updated',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Store the state necessary to power undo / redo.';
--;;
CREATE TABLE `data_permissions` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'The ID of the permission',
  `group_id` int NOT NULL COMMENT 'The ID of the associated permission group',
  `perm_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The type of the permission (e.g. "data", "collection", "download"...)',
  `db_id` int NOT NULL COMMENT 'A database ID, for DB and table-level permissions',
  `schema_name` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'A schema name, for table-level permissions',
  `table_id` int DEFAULT NULL COMMENT 'A table ID',
  `perm_value` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The value this permission is set to.',
  `unique_perms_helper` int GENERATED ALWAYS AS (coalesce(`table_id`,-(1))) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_data_permissions` (`group_id`,`perm_type`,`db_id`,`unique_perms_helper`),
  KEY `idx_data_permissions_table_id` (`table_id`),
  KEY `idx_data_permissions_db_id` (`db_id`),
  KEY `idx_data_permissions_group_id` (`group_id`),
  KEY `idx_data_permissions_group_id_db_id_perm_value` (`group_id`,`db_id`,`perm_value`),
  KEY `idx_data_permissions_group_id_db_id_table_id_perm_value` (`group_id`,`db_id`,`table_id`,`perm_value`),
  CONSTRAINT `fk_data_permissions_ref_db_id` FOREIGN KEY (`db_id`) REFERENCES `metabase_database` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_data_permissions_ref_permissions_group` FOREIGN KEY (`group_id`) REFERENCES `permissions_group` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_data_permissions_ref_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A table to store database and table permissions';
--;;
CREATE TABLE `db_router` (
  `id` int NOT NULL AUTO_INCREMENT,
  `database_id` int NOT NULL COMMENT 'The ID of the database this is for.',
  `user_attribute` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The user attribute used to redirect users to a different database.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `database_id` (`database_id`),
  CONSTRAINT `fk_db_router_database_id` FOREIGN KEY (`database_id`) REFERENCES `metabase_database` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Configuration for Database Routers. Currently just holds which user attribute each\nconfigured router database should use to choose a mirror database to route to.\n';
--;;
CREATE TABLE `dependency` (
  `id` int NOT NULL AUTO_INCREMENT,
  `from_entity_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The type of the dependent entity',
  `from_entity_id` int NOT NULL COMMENT 'The ID of the dependent entity',
  `to_entity_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The type of the entity depended on',
  `to_entity_id` int NOT NULL COMMENT 'The ID of the entity depended on',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_dependency` (`from_entity_type`,`from_entity_id`,`to_entity_type`,`to_entity_id`),
  KEY `idx_dependency_from` (`from_entity_type`,`from_entity_id`),
  KEY `idx_dependency_to` (`to_entity_type`,`to_entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A table to track dependencies between Metabase entities';
--;;
CREATE TABLE `dependency_status` (
  `id` int NOT NULL AUTO_INCREMENT,
  `entity_type` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The type of the entity (card, transform, snippet, etc.)',
  `entity_id` int NOT NULL COMMENT 'The ID of the entity',
  `analysis_version` smallint NOT NULL DEFAULT '0',
  `fail_count` int NOT NULL DEFAULT '0' COMMENT 'Number of consecutive failed dependency calculation attempts',
  `terminal` bit(1) NOT NULL DEFAULT b'0' COMMENT 'True when the entity has exceeded max retries and should not be retried until modified',
  `stale` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_dependency_status` (`entity_type`,`entity_id`),
  KEY `idx_dependency_status_stale` (`stale`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tracks dependency calculation status for entities, analogous to analysis_finding';
--;;
CREATE TABLE `dimension` (
  `id` int NOT NULL AUTO_INCREMENT,
  `field_id` int NOT NULL COMMENT 'ID of the field this dimension row applies to',
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Short description used as the display name of this new column',
  `type` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Either internal for a user defined remapping or external for a foreign key based remapping',
  `human_readable_field_id` int DEFAULT NULL COMMENT 'Only used with external type remappings. Indicates which field on the FK related table to use for display',
  `created_at` timestamp(6) NOT NULL,
  `updated_at` timestamp(6) NOT NULL,
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_dimension_field_id` (`field_id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `fk_dimension_displayfk_ref_field_id` (`human_readable_field_id`),
  KEY `idx_dimension_field_id` (`field_id`),
  CONSTRAINT `fk_dimension_displayfk_ref_field_id` FOREIGN KEY (`human_readable_field_id`) REFERENCES `metabase_field` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_dimension_ref_field_id` FOREIGN KEY (`field_id`) REFERENCES `metabase_field` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores references to alternate views of existing fields, such as remapping an integer to a description, like an enum';
--;;
CREATE TABLE `document` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `name` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Document name',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the document was created',
  `document` longtext COLLATE utf8mb4_unicode_ci COMMENT 'content of the document',
  `content_type` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'the content_type of the document column',
  `creator_id` int NOT NULL COMMENT 'User who created this document',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the document was updated',
  `collection_id` int DEFAULT NULL COMMENT 'What collection I live in. Null if it''s Our Analytics.',
  `archived` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Has this document been archived?',
  `archived_directly` bit(1) DEFAULT b'0' COMMENT 'Was this thing trashed directly',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `last_viewed_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp of when this document was last viewed',
  `view_count` int NOT NULL DEFAULT '0' COMMENT 'Keeps a running count of document views',
  `collection_position` int DEFAULT NULL COMMENT 'Collection position used for pinning documents. Higher numbers = pinned, null = not pinned.',
  `public_uuid` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `made_public_by_id` int DEFAULT NULL COMMENT 'ID of the user who made this document public',
  `public_uuid_prefix` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Plaintext leading characters of public_uuid, used as an indexed narrowing key for public-link lookups.',
  `exploration_id` int DEFAULT NULL COMMENT 'Optional owning exploration. When set, this document is the exploration''s Summary and is not first-class content (hidden from search, collections, recents).',
  `is_placeholder` bit(1) NOT NULL DEFAULT b'0' COMMENT 'True while the document is still an untouched auto-created placeholder (exploration Summary). Cleared on the first body save or chart append.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  UNIQUE KEY `idx_document_public_uuid` (`public_uuid`),
  KEY `idx_document_creator_id` (`creator_id`),
  KEY `idx_document_collection_id` (`collection_id`),
  KEY `idx_document_made_public_by_id` (`made_public_by_id`),
  KEY `idx_document_public_uuid_prefix` (`public_uuid_prefix`),
  KEY `idx_document_exploration_id` (`exploration_id`),
  CONSTRAINT `fk_document_exploration_id` FOREIGN KEY (`exploration_id`) REFERENCES `exploration` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_document_made_public_by_id` FOREIGN KEY (`made_public_by_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_document_ref_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_document_ref_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Documents table';
--;;
CREATE TABLE `document_bookmark` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `user_id` int NOT NULL COMMENT 'User who bookmarked the document',
  `document_id` int NOT NULL COMMENT 'The document that was bookmarked',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp when the bookmark was created',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_document_bookmark_user_document_unique` (`user_id`,`document_id`),
  KEY `idx_document_bookmark_user_id` (`user_id`),
  KEY `idx_document_bookmark_document_id` (`document_id`),
  CONSTRAINT `fk_document_bookmark_document_id` FOREIGN KEY (`document_id`) REFERENCES `document` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_document_bookmark_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Store user bookmarks for documents';
--;;
CREATE TABLE `embedding_sdk_react_18_host` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `host` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Hostname of the host app page, or an empty string when the page URL has no hostname',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the host was first recorded',
  `last_seen_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the host was last recorded',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_embedding_sdk_react_18_host_host` (`host`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Host apps that used the React embedding SDK with React 18';
--;;
CREATE TABLE `embedding_theme` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of the embed theme',
  `settings` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON object of theme settings',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp when the theme was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp when the theme was last updated',
  `is_default` bit(1) NOT NULL DEFAULT b'0' COMMENT 'True for the Light/Dark themes Metabase seeds on first visit to the themes page. Nothing else can tell them apart - names are stored translated, and seeding is lazy so ids are not ordered. Existing rows are deliberately left false, so instances that already have themes count them as user-created.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores themes created via the embedding theme editor';
--;;
CREATE TABLE `exploration` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `name` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Human-readable name for the exploration',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Optional longer description of what is being investigated',
  `creator_id` int NOT NULL COMMENT 'User who created the exploration; owns it for permissions',
  `collection_id` int DEFAULT NULL COMMENT 'Collection this exploration lives in. NULL means the root collection ("Our Analytics"). The API stores whatever collection_id the caller supplies (the frontend pre-selects the creator''s Personal Collection when creating a new exploration).',
  `archived` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the exploration has been archived',
  `archived_directly` bit(1) NOT NULL DEFAULT b'0' COMMENT 'True when the user archived this exploration itself; false when it became archived because a parent collection was archived',
  `collection_position` int DEFAULT NULL COMMENT 'Ordering of pinned items within a collection; null = not pinned',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the exploration was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the exploration was last updated',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_exploration_creator_id` (`creator_id`),
  KEY `idx_exploration_collection_id` (`collection_id`),
  CONSTRAINT `fk_exploration_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_exploration_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A user-created data investigation, e.g. "why is revenue down".';
--;;
CREATE TABLE `exploration_block` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key — surfaced to the FE as the block id',
  `exploration_thread_id` int NOT NULL COMMENT 'The thread this block belongs to',
  `metrics` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of selected metrics ({card_id, dimension_mappings}) for this block',
  `dimensions` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of selected dimensions ({dimension_id, display_name, effective_type, semantic_type}) for this block',
  `position` int NOT NULL DEFAULT '0' COMMENT 'Authoring order of the block within a thread',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the block was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the block was last updated',
  PRIMARY KEY (`id`),
  KEY `idx_exploration_block_thread_id` (`exploration_thread_id`),
  CONSTRAINT `fk_exploration_block_thread_id` FOREIGN KEY (`exploration_thread_id`) REFERENCES `exploration_thread` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One Research-plan block selected on a thread — a set of metrics crossed with a set of dimensions. Immutable after create.';
--;;
CREATE TABLE `exploration_bookmark` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `user_id` int NOT NULL COMMENT 'User who bookmarked the exploration',
  `exploration_id` int NOT NULL COMMENT 'The exploration that was bookmarked',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp when the bookmark was created',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_exploration_bookmark_user_exploration_unique` (`user_id`,`exploration_id`),
  KEY `idx_exploration_bookmark_user_id` (`user_id`),
  KEY `idx_exploration_bookmark_exploration_id` (`exploration_id`),
  CONSTRAINT `fk_exploration_bookmark_exploration_id` FOREIGN KEY (`exploration_id`) REFERENCES `exploration` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_exploration_bookmark_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Store user bookmarks for explorations';
--;;
CREATE TABLE `exploration_page` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key — the page''s stable identity, surfaced to the FE',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `exploration_block_id` int NOT NULL COMMENT 'The block this page belongs to. Mutable parent — a future re-grouping can move a page between blocks without changing its id.',
  `card_id` int NOT NULL COMMENT 'Metric Card — part of the page''s grouping/reconciliation key',
  `dimension_id` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Virtual dimension ID — part of the page''s grouping/reconciliation key',
  `query_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'default' COMMENT 'Generator variant — part of the page''s grouping/reconciliation key',
  `position` int NOT NULL DEFAULT '0' COMMENT 'First-seen authoring order of the page within its block',
  `starred` bit(1) NOT NULL DEFAULT b'0' COMMENT 'True if the page is starred',
  `hidden` bit(1) NOT NULL DEFAULT b'0' COMMENT 'True if the page is hidden from the sidebar',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the page was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the page was last updated',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_exploration_page_block_id` (`exploration_block_id`),
  KEY `idx_exploration_page_card_id` (`card_id`),
  CONSTRAINT `fk_exploration_page_block_id` FOREIGN KEY (`exploration_block_id`) REFERENCES `exploration_block` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_exploration_page_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A page within a block — the queries for one (card, dimension, query_type), bundled under a stable id so comments/stars can anchor to it across reruns.';
--;;
CREATE TABLE `exploration_query` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `exploration_thread_id` int NOT NULL COMMENT 'The thread this query belongs to',
  `page_id` int NOT NULL COMMENT 'The exploration_page this query is reconciled under. The reconciler stamps it on every query, so it''s required from the start.',
  `name` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Optional display name for the chart',
  `card_id` int NOT NULL COMMENT 'The metric Card this chart is for',
  `database_id` int NOT NULL COMMENT 'Database the snapshot MBQL runs against, frozen alongside `dataset_query` at plan time. Lets the worker build the metadata provider and the data-permission gate read the database without parsing `dataset_query` or joining to the Card.',
  `segment_id` int DEFAULT NULL COMMENT 'Optional segment applied as a filter on top of (card, dimension); null for the unsegmented base query',
  `dimension_id` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Virtual dimension ID used as the breakout for this chart',
  `query_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'default' COMMENT 'Generator variant — one of default, temporal-pattern-day, temporal-pattern-hour, time-facet, top-n-other, per-value-time-series, filtered-subset',
  `display` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Chart display type (line, bar, etc.)',
  `visualization_settings` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON visualization settings for this chart',
  `dataset_query` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Snapshot MBQL produced at "Start" time; null until the runner lazily builds it at execution time',
  `params` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON-encoded variant params consumed by the runner when finalizing the chart MBQL just before execution. Shape depends on variant — top-n-other carries a k; filtered-subset carries filter_values; per-value-time-series carries k plus value_index plus optional temporal_dimension_id.',
  `position` int NOT NULL DEFAULT '0' COMMENT 'Ordering of queries within a thread',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'Worker state machine; one of pending, running, done, error',
  `error_message` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Error message captured when the worker fails to execute the query',
  `started_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When the worker started executing this query',
  `finished_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When the worker finished executing this query (success or error)',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the query was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the query was last updated',
  `data_access_token` longtext COLLATE utf8mb4_unicode_ci COMMENT 'EDN sandbox/impersonation/routing fingerprint of the creator''s lens when this row was finalized; null until then',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_exploration_query_thread_id` (`exploration_thread_id`),
  KEY `idx_exploration_query_card_id` (`card_id`),
  KEY `idx_exploration_query_segment_id` (`segment_id`),
  KEY `idx_exploration_query_status` (`status`),
  KEY `idx_exploration_query_database_id` (`database_id`),
  KEY `idx_exploration_query_page_id` (`page_id`),
  CONSTRAINT `fk_exploration_query_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_exploration_query_database_id` FOREIGN KEY (`database_id`) REFERENCES `metabase_database` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_exploration_query_page_id` FOREIGN KEY (`page_id`) REFERENCES `exploration_page` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_exploration_query_segment_id` FOREIGN KEY (`segment_id`) REFERENCES `segment` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_exploration_query_thread_id` FOREIGN KEY (`exploration_thread_id`) REFERENCES `exploration_thread` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A chart definition produced when "Start exploration" is run on a thread.';
--;;
CREATE TABLE `exploration_query_result` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `exploration_query_id` int NOT NULL COMMENT 'The exploration_query this result belongs to',
  `stored_result_id` int NOT NULL COMMENT 'FK to the cached snapshot in stored_result',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the result was written',
  `interestingness_score` double DEFAULT NULL COMMENT 'Chart interestingness score in [0.0, 1.0]; null when the result can''t be meaningfully scored (e.g. empty rows, no numeric measure).',
  `contextual_interestingness_score` double DEFAULT NULL COMMENT 'LLM-backed relevance score in [0.0, 1.0] for the chart vs. the thread prompt; null when the LLM is unconfigured, the prompt is blank, or the call failed.',
  `chart_stats` longtext COLLATE utf8mb4_unicode_ci COMMENT 'EDN-encoded raw stats on the chart',
  `metric_description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Description of the underlying metric in business terms',
  `chart_description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Description of the metric+dimension combination',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_exploration_query_result_query_id` (`exploration_query_id`),
  KEY `idx_exploration_query_result_stored_result_id` (`stored_result_id`),
  CONSTRAINT `fk_exploration_query_result_query_id` FOREIGN KEY (`exploration_query_id`) REFERENCES `exploration_query` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_exploration_query_result_stored_result_id` FOREIGN KEY (`stored_result_id`) REFERENCES `stored_result` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Per-exploration_query record pointing at the cached snapshot in stored_result plus the exploration-specific scoring metadata. Keyed 1:1 to exploration_query.';
--;;
CREATE TABLE `exploration_thread` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `exploration_id` int NOT NULL COMMENT 'The exploration this thread belongs to',
  `name` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Optional name for the thread / hypothesis',
  `prompt` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Natural-language prompt the user typed for this thread',
  `position` int NOT NULL DEFAULT '0' COMMENT 'Ordering of threads within an exploration',
  `source_page_id` int DEFAULT NULL COMMENT 'Page (chart) this thread was drilled from via explore-further; null for top-level threads',
  `started_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Set when the user clicks "Start exploration"; null means draft',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the thread was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the thread was last updated',
  `completed_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Set once when every query in the thread has reached a terminal status (done or error). Used as a CAS gate so completion handlers fire exactly once.',
  `analysis_started_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Set once when every query in the thread has reached a terminal status. CAS gate that ensures the auto-insights handler fires exactly once per thread. completed_at is set later, when the handler finishes.',
  `query_plan_started_at` timestamp(6) NULL DEFAULT NULL COMMENT 'CAS-claim marker for the background query-planning step. Set by the planning worker the moment it begins; subsequent workers skip threads whose marker is already set so planning runs exactly once per thread.',
  `query_plan_transcript` longtext COLLATE utf8mb4_unicode_ci COMMENT 'EDN-encoded transcript of the planning run (planner, outcome, validation errors, final plan) used to materialize this thread''s exploration_query rows. Debug-only — not surfaced to the user.',
  `canceled_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Set when the user stops a running thread via the cancel endpoint. Set together with `completed_at` so existing terminal-state predicates keep working; `canceled_at IS NOT NULL` is the cause marker that distinguishes a cancel from a natural completion.',
  `data_access_token` longtext COLLATE utf8mb4_unicode_ci COMMENT 'EDN sandbox/impersonation/routing fingerprint of the lens this thread was derived under.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_exploration_thread_exploration_id` (`exploration_id`),
  KEY `idx_exploration_thread_source_page_id` (`source_page_id`),
  CONSTRAINT `fk_exploration_thread_exploration_id` FOREIGN KEY (`exploration_id`) REFERENCES `exploration` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_exploration_thread_source_page_id` FOREIGN KEY (`source_page_id`) REFERENCES `exploration_page` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A hypothesis / iteration within an exploration.';
--;;
CREATE TABLE `exploration_thread_timeline` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `exploration_thread_id` int NOT NULL COMMENT 'The thread this timeline belongs to',
  `timeline_id` int NOT NULL COMMENT 'The associated timeline',
  `position` int NOT NULL DEFAULT '0' COMMENT 'Ordering of timelines within a thread',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the selection was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the selection was last updated',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_exploration_thread_timeline_thread_timeline` (`exploration_thread_id`,`timeline_id`),
  KEY `idx_exploration_thread_timeline_timeline_id` (`timeline_id`),
  CONSTRAINT `fk_exploration_thread_timeline_thread_id` FOREIGN KEY (`exploration_thread_id`) REFERENCES `exploration_thread` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_exploration_thread_timeline_timeline_id` FOREIGN KEY (`timeline_id`) REFERENCES `timeline` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Timelines associated with a thread.';
--;;
CREATE TABLE `glossary` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key identifier for glossary entries',
  `term` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The glossary term or phrase being defined',
  `definition` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The detailed definition or explanation of the term',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp when comment was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp when comment was last updated',
  `creator_id` int NOT NULL DEFAULT '13371338' COMMENT 'User who created this glossary entry',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `term` (`term`),
  UNIQUE KEY `uq_glossary_entity_id` (`entity_id`),
  KEY `idx_glossary_creator_id` (`creator_id`),
  CONSTRAINT `fk_glossary_ref_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to store glossary terms and their definitions';
--;;
CREATE TABLE `health_inspector_runs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `message` longtext COLLATE utf8mb4_unicode_ci COMMENT 'A message to show to the instance admin.',
  `check_name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The name of the check',
  `run_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When it was run',
  `health` int NOT NULL COMMENT 'Health as a percentage out of 100',
  PRIMARY KEY (`id`),
  KEY `idx_health_inspector_runs_check_time` (`check_name`,`run_at`,`id`),
  KEY `idx_health_inspector_runs_run_at` (`run_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Records status of health inspector runs over time';
--;;
CREATE TABLE `impersonation_query_cache` (
  `id` int NOT NULL AUTO_INCREMENT,
  `input_version` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Metabase version that validated the query; rows from other versions are never read',
  `input_engine` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Driver that validated the query',
  `input_allow_write` bit(1) NOT NULL COMMENT 'Whether the query was validated as a write statement rather than a select',
  `input_admin` bit(1) NOT NULL COMMENT 'Whether the query was validated for an admin, who is allowed more than other users',
  `input_query_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA-256 hex of input_query, used to look the row up',
  `input_query` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Native SQL of the stage after parameter substitution',
  `result` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Validation outcome: valid, unparseable, unvalidatable or invalid',
  `result_query` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Validated SQL to run in place of input_query, set only when result is valid',
  `result_reason` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Why the validator could not check the query, when it says',
  `created_at` timestamp(6) NOT NULL COMMENT 'Timestamp when the result was cached',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_impersonation_query_cache_input` (`input_query_hash`,`input_engine`,`input_allow_write`,`input_admin`,`input_version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Cached validation results of native query stages run on impersonated databases';
--;;
CREATE TABLE `implicit_action` (
  `action_id` int NOT NULL COMMENT 'The associated action',
  `kind` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The kind of implicit action create/update/delete',
  `table_id` int DEFAULT NULL COMMENT 'The table the implicit action writes to',
  PRIMARY KEY (`action_id`),
  KEY `idx_implicit_action_table_id` (`table_id`),
  CONSTRAINT `fk_implicit_action_action_id` FOREIGN KEY (`action_id`) REFERENCES `action` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_implicit_action_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='An action with dynamic parameters based on the underlying model';
--;;
CREATE TABLE `label` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `icon` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_label_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `login_history` (
  `id` int NOT NULL AUTO_INCREMENT,
  `timestamp` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When this login occurred.',
  `user_id` int NOT NULL COMMENT 'ID of the User that logged in.',
  `session_id` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ID of the Session created by this login if one is currently active. NULL if Session is no longer active.',
  `device_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Cookie-based unique identifier for the device/browser the user logged in from.',
  `device_description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `ip_address` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_session_id` (`session_id`),
  KEY `idx_timestamp` (`timestamp`),
  KEY `idx_user_id_timestamp` (`user_id`,`timestamp`),
  KEY `idx_user_id_device_id` (`user_id`,`device_id`),
  CONSTRAINT `fk_login_history_session_id` FOREIGN KEY (`session_id`) REFERENCES `core_session` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_login_history_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Keeps track of various logins for different users and additional info such as location and device';
--;;
CREATE TABLE `mcp_feedback` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Surrogate PK',
  `user_id` int NOT NULL COMMENT 'The Metabase user who submitted the feedback. Unconstrained int (matches metabot_feedback precedent) so rows survive user deletion.',
  `positive` bit(1) NOT NULL COMMENT 'true = thumbs up, false = thumbs down',
  `issue_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Optional structured issue category (e.g. "wrong-visualization")',
  `freeform_feedback` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Optional freeform comment',
  `prompt` longtext COLLATE utf8mb4_unicode_ci COMMENT 'User prompt that produced the visualization, when available',
  `query` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Encoded ad-hoc query that was being shown, when available',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the feedback was submitted',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='User feedback on MCP Apps visualizations - positive/negative w/ optional reason + comment';
--;;
CREATE TABLE `mcp_group_permission` (
  `id` int NOT NULL AUTO_INCREMENT,
  `group_id` int NOT NULL COMMENT 'The ID of the associated permissions group',
  `mcp_enabled` bit(1) NOT NULL COMMENT 'Whether members of the group may connect to the MCP server',
  `tool_access` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON object from MCP tool name to yes or no; an absent tool takes the author''s default',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp this row was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp this row was last updated',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_mcp_group_permission_group_id` (`group_id`),
  CONSTRAINT `fk_mcp_group_permission_ref_permissions_group` FOREIGN KEY (`group_id`) REFERENCES `permissions_group` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MCP access and per-tool overrides per permissions group';
--;;
