CREATE TABLE `mcp_query_handle` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Handle UUID; returned to the iframe and threaded through to the MCP tool call',
  `mcp_session_id` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL,
  `core_session_id` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'core_session.id when one has been materialized; cascade-deletes with the session',
  `encoded_query` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Base64-encoded MBQL query payload',
  `created_at` timestamp(6) NOT NULL COMMENT 'When this handle was stored; useful for debugging and future TTL cleanup',
  `prompt` longtext COLLATE utf8mb4_unicode_ci COMMENT 'The user''s original prompt used to construct the query; nullable for drill-through handles',
  PRIMARY KEY (`id`),
  KEY `idx_mcp_query_handle_mcp_session_id` (`mcp_session_id`),
  KEY `idx_mcp_query_handle_core_session_id` (`core_session_id`),
  CONSTRAINT `fk_mcp_query_handle_ref_core_session` FOREIGN KEY (`core_session_id`) REFERENCES `core_session` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Server-side store for encoded MBQL query payloads referenced by MCP tool calls';
--;;
CREATE TABLE `mcp_session_log` (
  `id` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MCP session id (primary key)',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the session was opened (initialize handshake)',
  `ended_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When the session was torn down (DELETE); NULL when the client never sent a clean teardown',
  `user_id` int DEFAULT NULL COMMENT 'Metabase user behind the session; NULL for system/unauthenticated. Non-PII, always recorded.',
  `tenant_id` int DEFAULT NULL COMMENT 'Snapshot of the user''s tenant at session time; NULL for non-tenant users. Non-PII, always recorded.',
  `client_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client name from the initialize handshake clientInfo (e.g. claude, chatgpt, cursor-vscode). Non-PII.',
  `client_version` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client version from the initialize handshake clientInfo. Non-PII.',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client IP captured at initialize, PII (gated by analytics-pii-retention-enabled).',
  `user_agent` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Raw User-Agent header captured at initialize, PII (gated).',
  PRIMARY KEY (`id`),
  KEY `idx_mcp_session_log_user_id` (`user_id`),
  KEY `idx_mcp_session_log_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One row per MCP session; client identity + PII captured once at the initialize handshake (modeled on metabot_conversation)';
--;;
CREATE TABLE `mcp_tool_call_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Autoincrement primary key',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the tool call was made',
  `user_id` int DEFAULT NULL COMMENT 'Metabase user who triggered the call; duplicated here for group-by convenience (mirrors ai_usage_log.user_id). Non-PII.',
  `tool_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of the MCP tool that was invoked',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Outcome of the call, e.g. success or error',
  `duration_ms` int DEFAULT NULL COMMENT 'Wall-clock duration of the tool call in milliseconds',
  `error_code` int DEFAULT NULL COMMENT 'JSON-RPC error code for a failed tool call (e.g. -32602, -32603); NULL on success. Non-PII, always recorded.',
  `error_message` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON-RPC error message for a failed tool call, PII (gated by analytics-pii-retention-enabled, truncated); NULL on success or when gating is off.',
  `client_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Canonical MCP client key (claude/chatgpt/cursor-vscode/vscode/zed/other), resolved at call time from _meta clientInfo or the session''s stored identity. Non-PII.',
  `client_version` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MCP client version, resolved at call time. Non-PII.',
  `tenant_id` int DEFAULT NULL COMMENT 'Snapshot of the calling user''s tenant at call time; NULL for non-tenant users. Non-PII.',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client IP captured at call time, PII (gated by analytics-pii-retention-enabled).',
  `user_agent` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Raw User-Agent captured at call time, PII (gated).',
  `sanitized_user_agent` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Sanitized (browser/OS) User-Agent descriptor, PII (gated).',
  PRIMARY KEY (`id`),
  KEY `idx_mcp_tool_call_log_user_id` (`user_id`),
  KEY `idx_mcp_tool_call_log_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One row per MCP tools/call; client identity + PII denormalized on so the view needs no session join (modeled on ai_usage_log)';
--;;
CREATE TABLE `measure` (
  `id` int NOT NULL AUTO_INCREMENT,
  `table_id` int NOT NULL COMMENT 'Foreign key to metabase_table',
  `creator_id` int NOT NULL COMMENT 'Foreign key to core_user who created this measure',
  `name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of the measure',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Optional description of the measure',
  `archived` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the measure has been archived',
  `definition` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON MBQL query containing the aggregation definition',
  `created_at` timestamp(6) NOT NULL COMMENT 'Timestamp when this measure was created',
  `updated_at` timestamp(6) NOT NULL COMMENT 'Timestamp when this measure was last updated',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `dimensions` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of persisted dimension definitions (id, display-name, types)',
  `dimension_mappings` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of dimension-to-field mappings (dimension-id, target, table-id)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_measure_table_id` (`table_id`),
  KEY `idx_measure_creator_id` (`creator_id`),
  CONSTRAINT `fk_measure_ref_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_measure_ref_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores saved aggregation expressions tied to tables';
--;;
CREATE TABLE `metabase_cluster_lock` (
  `lock_name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'a single column that can be used to a lock across a cluster',
  PRIMARY KEY (`lock_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A table to allow metabase instances to take locks across a cluster';
--;;
CREATE TABLE `metabase_database` (
  `id` int NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `details` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `engine` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_sample` bit(1) NOT NULL DEFAULT b'0',
  `is_full_sync` bit(1) NOT NULL DEFAULT b'1',
  `points_of_interest` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `caveats` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `metadata_sync_schedule` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0 50 * * * ? *' COMMENT 'The cron schedule string for when this database should undergo the metadata sync process (and analysis for new fields).',
  `cache_field_values_schedule` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `timezone` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Timezone identifier for the database, set by the sync process',
  `is_on_demand` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether we should do On-Demand caching of FieldValues for this DB. This means FieldValues are updated when their Field is used in a Dashboard or Card param.',
  `auto_run_queries` bit(1) NOT NULL DEFAULT b'1' COMMENT 'Whether to automatically run queries when doing simple filtering and summarizing in the Query Builder.',
  `refingerprint` bit(1) DEFAULT NULL COMMENT 'Whether or not to enable periodic refingerprinting for this Database.',
  `cache_ttl` int DEFAULT NULL COMMENT 'Granular cache TTL for specific database.',
  `initial_sync_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'complete' COMMENT 'String indicating whether a database has completed its initial sync and is ready to use',
  `creator_id` int DEFAULT NULL COMMENT 'ID of the admin who added the database',
  `settings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Serialized JSON containing Database-local Settings for this Database',
  `dbms_version` longtext COLLATE utf8mb4_unicode_ci COMMENT 'A JSON object describing the flavor and version of the DBMS.',
  `is_audit` bit(1) NOT NULL DEFAULT b'0',
  `uploads_enabled` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether uploads are enabled for this database',
  `uploads_schema_name` longtext COLLATE utf8mb4_unicode_ci COMMENT 'The schema name for uploads',
  `uploads_table_prefix` longtext COLLATE utf8mb4_unicode_ci COMMENT 'The prefix for upload table names',
  `is_attached_dwh` bit(1) NOT NULL DEFAULT b'0' COMMENT 'This is an attached data warehouse, do not serialize it and hide its details from the UI',
  `router_database_id` int DEFAULT NULL COMMENT 'The ID of the primary database for this mirror database.',
  `provider_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The name of the hosting provider for the database (e.g., AWS RDS, Azure).',
  `write_data_details` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Encrypted JSON containing connection details for write operations (transforms, etc.)',
  `is_stub` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Placeholder database created during deserialization; cleared when real details are supplied and the connection test passes',
  `default_schema` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Schema used to resolve unqualified table references; null for databases without schemas',
  `initial_sync_error` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Message of the error that aborted the initial sync; null unless initial_sync_status is aborted',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_metabase_database_router_database_id_name` (`router_database_id`,`name`),
  KEY `fk_database_creator_id` (`creator_id`),
  CONSTRAINT `fk_database_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_metabase_database_metabase_database_id` FOREIGN KEY (`router_database_id`) REFERENCES `metabase_database` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `metabase_field` (
  `id` int NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL,
  `updated_at` timestamp(6) NOT NULL,
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `base_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `semantic_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `active` bit(1) NOT NULL DEFAULT b'1',
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `preview_display` bit(1) NOT NULL DEFAULT b'1',
  `position` int NOT NULL DEFAULT '0',
  `table_id` int NOT NULL,
  `parent_id` int DEFAULT NULL,
  `display_name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `visibility_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `fk_target_field_id` int DEFAULT NULL,
  `last_analyzed` timestamp(6) NULL DEFAULT NULL,
  `points_of_interest` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `caveats` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `fingerprint` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `fingerprint_version` int NOT NULL DEFAULT '0' COMMENT 'The version of the fingerprint for this Field. Used so we can keep track of which Fields need to be analyzed again when new things are added to fingerprints.',
  `database_type` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `has_field_values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `settings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `database_position` int NOT NULL DEFAULT '0',
  `custom_position` int NOT NULL DEFAULT '0',
  `effective_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The effective type of the field after any coercions.',
  `coercion_strategy` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'A strategy to coerce the base_type into the effective_type.',
  `nfc_path` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nested field column paths, flattened',
  `database_required` bit(1) NOT NULL DEFAULT b'0',
  `json_unfolding` bit(1) NOT NULL DEFAULT b'0',
  `database_is_auto_increment` bit(1) NOT NULL DEFAULT b'0',
  `database_indexed` bit(1) DEFAULT NULL,
  `database_partitioned` bit(1) DEFAULT NULL,
  `is_defective_duplicate` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Indicates whether column is a defective duplicate field that should never have been created.',
  `unique_field_helper` int GENERATED ALWAYS AS ((case when (`is_defective_duplicate` = true) then NULL else (case when (`parent_id` is null) then 0 else `parent_id` end) end)) STORED,
  `database_is_pk` bit(1) DEFAULT NULL COMMENT 'Whether or not the field is part of the primary key (not user editable like semantic_type)',
  `database_is_nullable` bit(1) DEFAULT NULL COMMENT 'Whether or not the field will accept nulls',
  `database_is_generated` bit(1) DEFAULT NULL COMMENT 'Whether or not the column is computed and will not accept writes',
  `database_default` longtext COLLATE utf8mb4_unicode_ci COMMENT 'The dialect specific column default expression',
  `dimension_interestingness` double DEFAULT NULL COMMENT 'Interestingness score (0.0-1.0) for this field when treated as a dimension in a metric.',
  `data_sensitivity` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Data sensitivity classification of the field. One of PII, SEC_KEY, PHI, PCI_FIN, BIO_GEN, SENS_PERS, CORP_IP, SYS_TELEMETRY, BIZ_CONF, PUBLIC.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_field` (`name`,`table_id`,`unique_field_helper`),
  KEY `idx_field_table_id` (`table_id`),
  KEY `idx_field_parent_id` (`parent_id`),
  KEY `idx_field_fk_target_field_id` (`fk_target_field_id`),
  CONSTRAINT `fk_field_fk_target_ref_field_id` FOREIGN KEY (`fk_target_field_id`) REFERENCES `metabase_field` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_field_parent_ref_field_id` FOREIGN KEY (`parent_id`) REFERENCES `metabase_field` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_field_ref_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `metabase_field_user_settings` (
  `field_id` int NOT NULL COMMENT 'The related Field',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the user setting was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the user setting was updated',
  `semantic_type` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set semantic_type for the Field',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'User-set description for the Field',
  `display_name` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set display_name for the Field',
  `visibility_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set visibility_type for the Field',
  `fk_target_field_id` int DEFAULT NULL COMMENT 'User-set fk_target_field_id for the Field',
  `has_field_values` longtext COLLATE utf8mb4_unicode_ci COMMENT 'User-set has_field_values for the Field',
  `effective_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set effective_type for the Field',
  `coercion_strategy` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set coercion_strategy for the Field',
  `caveats` longtext COLLATE utf8mb4_unicode_ci COMMENT 'User-set caveats for the Field',
  `points_of_interest` longtext COLLATE utf8mb4_unicode_ci COMMENT 'User-set points_of_interest for the Field',
  `nfc_path` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set nfc_path for the Field',
  `json_unfolding` bit(1) DEFAULT NULL COMMENT 'User-set json_unfolding for the Field',
  `settings` longtext COLLATE utf8mb4_unicode_ci COMMENT 'User-set settings for the Field',
  `data_sensitivity` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set data_sensitivity for the Field. A non-NULL value here overrides any value an automated writer puts in metabase_field.data_sensitivity.',
  `description_set` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the user set description, so a NULL description overrides the sync value.',
  `semantic_type_set` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the user set semantic_type, so a NULL semantic_type overrides the sync value.',
  `fk_target_field_id_set` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the user set fk_target_field_id, so a NULL fk_target_field_id overrides the sync value.',
  `custom_position` int DEFAULT NULL COMMENT 'User-set custom_position for the Field',
  PRIMARY KEY (`field_id`),
  KEY `idx_field_user_settings_fk_target_field_id` (`fk_target_field_id`),
  CONSTRAINT `fk_field_user_setting_field_id` FOREIGN KEY (`field_id`) REFERENCES `metabase_field` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_field_user_settings_fk_target_ref_field_id` FOREIGN KEY (`fk_target_field_id`) REFERENCES `metabase_field` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Mirror table of metabase_field to keep track of user-set values (only settable fields are mirrored)';
--;;
CREATE TABLE `metabase_fieldvalues` (
  `id` int NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `human_readable_values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `field_id` int NOT NULL,
  `has_more_values` bit(1) DEFAULT b'0',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'full' COMMENT 'Type of FieldValues',
  `hash_key` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Hash key for a cached fieldvalues',
  `last_used_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp of when these FieldValues were last used.',
  PRIMARY KEY (`id`),
  KEY `idx_fieldvalues_field_id` (`field_id`),
  CONSTRAINT `fk_fieldvalues_ref_field_id` FOREIGN KEY (`field_id`) REFERENCES `metabase_field` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `metabase_table` (
  `id` int NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL,
  `updated_at` timestamp(6) NOT NULL,
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `entity_type` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `active` bit(1) NOT NULL,
  `db_id` int NOT NULL,
  `display_name` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `visibility_type` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `schema` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `points_of_interest` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `caveats` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `show_in_getting_started` bit(1) NOT NULL DEFAULT b'0',
  `field_order` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'database',
  `initial_sync_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'complete' COMMENT 'String indicating whether a table has completed its initial sync and is ready to use',
  `is_upload` bit(1) NOT NULL DEFAULT b'0',
  `database_require_filter` bit(1) DEFAULT NULL,
  `estimated_row_count` bigint DEFAULT NULL COMMENT 'The estimated row count',
  `view_count` int NOT NULL DEFAULT '0' COMMENT 'Keeps a running count of card views',
  `is_defective_duplicate` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Indicates whether the table is a defective duplicate that should never have been created.',
  `unique_table_helper` varchar(254) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`is_defective_duplicate` = true) then NULL else coalesce(`schema`,_utf8mb4'') end)) STORED,
  `deactivated_at` timestamp(6) NULL DEFAULT NULL COMMENT 'The timestamp when the table was deactivated (active changed from true to false)',
  `archived_at` timestamp(6) NULL DEFAULT NULL COMMENT 'The timestamp when the table was marked for archiving',
  `is_writable` bit(1) DEFAULT NULL COMMENT 'true if current connection can insert, update and delete rows from this table',
  `data_authority` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unconfigured' COMMENT 'Indicates the data authority status - unconfigured, authoritative, computed, or ingested',
  `data_source` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The origin type of the data (e.g. metabase-transform)',
  `data_layer` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT 'internal' COMMENT 'The (new) enum for visibility class',
  `owner_email` longtext COLLATE utf8mb4_unicode_ci COMMENT 'An optional email address of the ''owner'' of this table, exclusive with owner_user_id.',
  `owner_user_id` int DEFAULT NULL COMMENT 'An (metabase) user id of the ''owner'' of this table, exclusive with owner_email.',
  `collection_id` int DEFAULT NULL COMMENT 'The collection this table is published to (null if not published or published to root)',
  `is_published` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether this table is published',
  `transform_id` int DEFAULT NULL COMMENT 'Foreign key to the transform that created this table',
  `transform_target` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether any transform is configured to target this table. Conservative: eagerly set to true when a transform targets this table (never stale in this direction), cleared asynchronously when no transforms reference it anymore (may have false positives, never false negatives).',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_uniq_table_db_id_schema_name` (`db_id`,`schema`,`name`),
  UNIQUE KEY `idx_unique_table` (`db_id`,`name`,`unique_table_helper`),
  KEY `idx_table_db_id` (`db_id`),
  KEY `idx_metabase_table_show_in_getting_started` (`show_in_getting_started`),
  KEY `idx_metabase_table_db_id_schema` (`db_id`,`schema`),
  KEY `idx_metabase_table_collection_id` (`collection_id`),
  KEY `idx_metabase_table_transform_id` (`transform_id`),
  CONSTRAINT `fk_metabase_table_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`),
  CONSTRAINT `fk_metabase_table_transform_id` FOREIGN KEY (`transform_id`) REFERENCES `transform` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_table_ref_database_id` FOREIGN KEY (`db_id`) REFERENCES `metabase_database` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `metabase_table_indexes` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Auto-incrementing primary key',
  `transform_id` int NOT NULL COMMENT 'FK to the transform that owns this index request',
  `index_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Physical index name, rendered verbatim into DDL',
  `structured` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON structured index definition (kind, columns, ...)',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'create-pending' COMMENT 'Lifecycle status: create-pending, update-pending, delete-pending, running, succeeded, or failed',
  `error_message` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Error from the last failed apply, if any',
  `created_by` int DEFAULT NULL COMMENT 'FK to core_user.id who created this request',
  `created_at` timestamp(6) NOT NULL COMMENT 'Timestamp when this request was created',
  `updated_at` timestamp(6) NOT NULL COMMENT 'Timestamp when this request was last updated',
  `last_executed_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Timestamp of the last apply attempt',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_table_indexes_transform_id_index_name` (`transform_id`,`index_name`),
  KEY `idx_table_indexes_created_by` (`created_by`),
  CONSTRAINT `fk_table_indexes_created_by` FOREIGN KEY (`created_by`) REFERENCES `core_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_table_indexes_transform_id` FOREIGN KEY (`transform_id`) REFERENCES `transform` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Index/clustering hints declared on a transform target, reapplied on each full transform run';
--;;
CREATE TABLE `metabase_table_user_settings` (
  `table_id` int NOT NULL COMMENT 'The related Table',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the user setting was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the user setting was updated',
  `display_name` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set display_name for the Table',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'User-set description for the Table',
  `entity_type` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set entity_type for the Table',
  `visibility_type` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set visibility_type for the Table',
  `caveats` longtext COLLATE utf8mb4_unicode_ci COMMENT 'User-set caveats for the Table',
  `points_of_interest` longtext COLLATE utf8mb4_unicode_ci COMMENT 'User-set points_of_interest for the Table',
  `data_layer` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set data_layer for the Table',
  `data_source` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set data_source for the Table',
  `owner_email` longtext COLLATE utf8mb4_unicode_ci COMMENT 'User-set owner_email for the Table',
  `owner_user_id` int DEFAULT NULL COMMENT 'User-set owner_user_id for the Table',
  `field_order` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set field_order for the Table; NOT NULL on metabase_table, so a NULL here means unset',
  `show_in_getting_started` bit(1) DEFAULT NULL COMMENT 'User-set show_in_getting_started for the Table; NOT NULL on metabase_table, so a NULL here means unset',
  `data_authority` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-set data_authority for the Table; NOT NULL on metabase_table, so a NULL here means unset',
  `is_published` bit(1) DEFAULT NULL COMMENT 'User-set is_published for the Table; NOT NULL on metabase_table, so a NULL here means unset',
  `collection_id` int DEFAULT NULL COMMENT 'User-set collection_id for the Table; set when is_published is, which answers for the pair',
  `description_set` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the user set description, so a NULL description overrides the sync value',
  `visibility_type_set` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the user set visibility_type, so a NULL visibility_type overrides the sync value',
  `caveats_set` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the user set caveats, so a NULL caveats overrides the sync value',
  `points_of_interest_set` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the user set points_of_interest, so a NULL points_of_interest overrides the sync value',
  `data_layer_set` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the user set data_layer, so a NULL data_layer overrides the sync value',
  `data_source_set` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the user set data_source, so a NULL data_source overrides the sync value',
  PRIMARY KEY (`table_id`),
  KEY `idx_table_user_settings_collection_id` (`collection_id`),
  KEY `idx_table_user_settings_owner_user_id` (`owner_user_id`),
  CONSTRAINT `fk_table_user_settings_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_table_user_settings_owner_user_id` FOREIGN KEY (`owner_user_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_table_user_settings_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='The values a user set on a Table; metabase_table keeps the ones sync wrote';
--;;
CREATE TABLE `metabot` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The name of the metabot',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Description of the metabot',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the metabot was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the metabot was updated',
  `use_verified_content` bit(1) DEFAULT b'0' COMMENT 'Whether this metabot should only use verified content',
  `collection_id` int DEFAULT NULL COMMENT 'ID of the collection this metabot can access',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Metabot configuration';
--;;
INSERT INTO `metabot` (`id`, `name`, `description`, `entity_id`, `created_at`, `updated_at`, `use_verified_content`, `collection_id`) VALUES (1,'Metabot','Metabot instance for internal users.','metabotmetabotmetabot','2026-11-03 11:45:13.000000','2026-11-03 11:45:13.000000',_binary '\0',NULL);
--;;
INSERT INTO `metabot` (`id`, `name`, `description`, `entity_id`, `created_at`, `updated_at`, `use_verified_content`, `collection_id`) VALUES (2,'Embedded Metabot','Metabot instance for embedded metabase users.','embeddedmetabotmetabo','2026-11-03 11:45:13.000000','2026-11-03 11:45:13.000000',_binary '\0',NULL);
--;;
CREATE TABLE `metabot_conversation` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Conversation UUID',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'created_at',
  `user_id` int NOT NULL COMMENT 'Reference to user having the conversation',
  `title` longtext COLLATE utf8mb4_unicode_ci,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client IP captured at conversation creation; NULL for Slack-originated conversations.',
  `slack_team_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Slack workspace team ID for Slack-originated Metabot conversations',
  `slack_channel_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Slack channel ID for Slack-originated Metabot conversations',
  `slack_thread_ts` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Slack root thread timestamp for Slack-originated Metabot conversations',
  `embedding_hostname` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Hostname extracted from the embed referrer header at conversation creation. Always populated when an embed referrer is present.',
  `embedding_path` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path extracted from the embed referrer header at conversation creation, PII.',
  `user_agent` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Raw User-Agent header captured at conversation creation, PII.',
  `sanitized_user_agent` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Sanitized User-Agent string (browser + OS family) at the originating conversation, for analytics display.',
  `forked_from_conversation_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Conversation this one was forked from, or null when not a fork',
  PRIMARY KEY (`id`),
  KEY `idx_metabot_conversation_user_id` (`user_id`),
  KEY `idx_metabot_conversation_created_at` (`created_at`),
  KEY `idx_metabot_conversation_forked_from_conversation_id` (`forked_from_conversation_id`),
  CONSTRAINT `fk_metabot_conversation_forked_from_conversation_id` FOREIGN KEY (`forked_from_conversation_id`) REFERENCES `metabot_conversation` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_metabot_conversation_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to store metabot conversation messages';
--;;
CREATE TABLE `metabot_feedback` (
  `message_id` int NOT NULL COMMENT 'PK + FK to metabot_message.id — enforces 1:1',
  `positive` bit(1) NOT NULL COMMENT 'true = thumbs up, false = thumbs down',
  `issue_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Optional structured issue category (e.g. "ui-bug", "not-factual")',
  `freeform_feedback` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Optional freeform comment',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the feedback was submitted',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the feedback was last updated',
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Surrogate PK',
  `user_id` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_metabot_feedback_message_id_user_id` (`message_id`,`user_id`),
  CONSTRAINT `fk_metabot_feedback_message_id` FOREIGN KEY (`message_id`) REFERENCES `metabot_message` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='User feedback - positive/negative w/ optional reason + comment';
--;;
CREATE TABLE `metabot_group_limit` (
  `id` int NOT NULL AUTO_INCREMENT,
  `group_id` int NOT NULL COMMENT 'The ID of the associated permissions group',
  `max_usage` int NOT NULL COMMENT 'The maximum usage value, interpreted according to the metabot-limit-unit setting',
  PRIMARY KEY (`id`),
  UNIQUE KEY `group_id` (`group_id`),
  CONSTRAINT `fk_metabot_group_limit_ref_permissions_group` FOREIGN KEY (`group_id`) REFERENCES `permissions_group` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Metabot usage limits per group';
--;;
CREATE TABLE `metabot_instance_limit` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tenant_id` int DEFAULT NULL COMMENT 'The tenant ID, or null for instance-wide limit',
  `max_usage` int DEFAULT NULL COMMENT 'The maximum usage value, interpreted according to the metabot-limit-unit setting. Null is unlimited',
  PRIMARY KEY (`id`),
  UNIQUE KEY `tenant_id` (`tenant_id`),
  CONSTRAINT `fk_metabot_instance_limit_ref_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenant` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Metabot usage limits at the instance or tenant level';
--;;
CREATE TABLE `metabot_message` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Autoincrement PK',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'created_at',
  `profile_id` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ai-service profile used to perform the conversation',
  `role` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Role of the sender',
  `data` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Full message content',
  `usage` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Can be null for user messages; {"<model-name>": {"prompt": 1, "completion": 2}}',
  `total_tokens` int NOT NULL COMMENT 'A sum of all prompt+completion from `usage`',
  `conversation_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Reference to a conversation',
  `slack_msg_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Slack message ID (ts) for correlating with Slack thread history',
  `channel_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Slack channel ID for correlating Slack responses',
  `deleted_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Soft delete timestamp for removed Slack metabot responses',
  `deleted_by_user_id` int DEFAULT NULL COMMENT 'Metabase user ID who removed the Slack metabot response',
  `user_id` int DEFAULT NULL COMMENT 'Metabase user ID associated with this message',
  `ai_proxied` bit(1) DEFAULT NULL COMMENT 'Whether this message was routed through the Metabase Cloud AI proxy (true) or directly via BYOK keys (false). Null for messages created before this migration.',
  `external_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Stable id shared with clients and used to resolve feedback submissions',
  `finished` bit(1) DEFAULT b'1' COMMENT 'NULL while in flight, true once completed, false if the client aborted mid-stream.',
  `error` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Error payload from the agent''s error stream part.',
  `data_version` int NOT NULL COMMENT 'Version of the data format stored in this message',
  `state` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Partial conversation state produced by this assistant turn',
  `forked_from_message_id` int DEFAULT NULL COMMENT 'Source message this row was copied from when forking, or null',
  `context_tokens` int DEFAULT NULL COMMENT 'Prompt + completion tokens of the turn''s final LLM call',
  `finish_reason` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Why a turn stopped early: length, content-filter or tool-calls. NULL when it ran to a normal stop.',
  `context_window_full` bit(1) DEFAULT NULL COMMENT 'True when the turn stopped at length with its context at or past the window of the model that ran it, so the next turn cannot fit. Metabase''s judgement at save time, not a provider value. NULL otherwise.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_metabot_message_external_id` (`external_id`),
  KEY `idx_metabot_message_conversation_id` (`conversation_id`),
  KEY `idx_metabot_message_channel_id_slack_msg_id` (`channel_id`,`slack_msg_id`),
  KEY `idx_metabot_message_user_id_conversation_id` (`user_id`,`conversation_id`),
  CONSTRAINT `fk_metabot_message_conversation_id` FOREIGN KEY (`conversation_id`) REFERENCES `metabot_conversation` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to store metabot conversation messages';
--;;
CREATE TABLE `metabot_permissions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `group_id` int NOT NULL COMMENT 'The ID of the associated permissions group',
  `perm_type` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The type of permission',
  `perm_value` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The value of the permission',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_metabot_permissions_group_id_perm_type` (`group_id`,`perm_type`),
  KEY `idx_metabot_permissions_group_id` (`group_id`),
  CONSTRAINT `fk_metabot_permissions_ref_permissions_group` FOREIGN KEY (`group_id`) REFERENCES `permissions_group` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A table to store metabot permissions per permissions group';
--;;
