CREATE TABLE `metabot_prompt` (
  `id` int NOT NULL AUTO_INCREMENT,
  `model` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The type of the entity this prompt is about',
  `card_id` int NOT NULL COMMENT 'The ID of the model or metric this prompt is about',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `prompt` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The text of the prompt',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the prompt was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the prompt was updated',
  `metabot_id` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_metabot_prompt_card_id` (`card_id`),
  KEY `idx_metabot_prompt_metabot_id` (`metabot_id`),
  CONSTRAINT `fk_metabot_prompt_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_metabot_prompt_metabot_id` FOREIGN KEY (`metabot_id`) REFERENCES `metabot` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Prompts of a metabot entity';
--;;
CREATE TABLE `metabot_source_feedback` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Auto-incrementing primary key',
  `message_id` int NOT NULL COMMENT 'FK to the Metabot message whose source was rated',
  `user_id` int NOT NULL COMMENT 'The Metabase user who submitted the feedback. Unconstrained int so audit rows survive user deletion.',
  `source_id` int NOT NULL COMMENT 'ID of the source object used by the response',
  `source_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of source object, e.g. table, card, or model',
  `positive` bit(1) NOT NULL COMMENT 'true = thumbs up, false = thumbs down',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the feedback was submitted',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the feedback was last updated',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_metabot_source_feedback_message_user_source` (`message_id`,`user_id`,`source_type`,`source_id`),
  KEY `idx_metabot_source_feedback_message_id` (`message_id`),
  CONSTRAINT `fk_metabot_source_feedback_message_id` FOREIGN KEY (`message_id`) REFERENCES `metabot_message` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='User feedback on sources used by Metabot responses';
--;;
CREATE TABLE `metabot_used_table` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Auto-incrementing primary key',
  `message_id` int NOT NULL COMMENT 'FK to the Metabot message whose query referenced this table',
  `table_id` int NOT NULL COMMENT 'FK to the underlying database table the generated query references',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When this reference was recorded',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_metabot_used_table_message_table` (`message_id`,`table_id`),
  KEY `idx_metabot_used_table_table_id` (`table_id`),
  CONSTRAINT `fk_metabot_used_table_message_id` FOREIGN KEY (`message_id`) REFERENCES `metabot_message` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_metabot_used_table_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Record of which database tables Metabot referenced in generated a queries. Source cards, models, and metrics are recursively expanded to their underlying tables before insertion.';
--;;
CREATE TABLE `metric` (
  `id` int NOT NULL AUTO_INCREMENT,
  `table_id` int NOT NULL,
  `creator_id` int NOT NULL,
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `archived` bit(1) DEFAULT b'0',
  `definition` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp(6) NOT NULL,
  `updated_at` timestamp(6) NOT NULL,
  `points_of_interest` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `caveats` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `how_is_this_calculated` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `show_in_getting_started` bit(1) NOT NULL DEFAULT b'0',
  `entity_id` char(21) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_metric_creator_id` (`creator_id`),
  KEY `idx_metric_table_id` (`table_id`),
  KEY `idx_metric_show_in_getting_started` (`show_in_getting_started`),
  CONSTRAINT `fk_metric_ref_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_metric_ref_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `metric_important_field` (
  `id` int NOT NULL AUTO_INCREMENT,
  `metric_id` int NOT NULL,
  `field_id` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_metric_important_field_metric_id_field_id` (`metric_id`,`field_id`),
  KEY `idx_metric_important_field_metric_id` (`metric_id`),
  KEY `idx_metric_important_field_field_id` (`field_id`),
  CONSTRAINT `fk_metric_important_field_metabase_field_id` FOREIGN KEY (`field_id`) REFERENCES `metabase_field` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_metric_important_field_metric_id` FOREIGN KEY (`metric_id`) REFERENCES `metric` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `model_index` (
  `id` int NOT NULL AUTO_INCREMENT,
  `model_id` int DEFAULT NULL COMMENT 'The ID of the indexed model.',
  `pk_ref` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Serialized JSON of the primary key field ref.',
  `value_ref` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Serialized JSON of the label field ref.',
  `schedule` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The cron schedule for when value syncing should happen.',
  `state` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The status of the index: initializing, indexed, error, overflow.',
  `indexed_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When the status changed',
  `error` longtext COLLATE utf8mb4_unicode_ci COMMENT 'The error message if the status is error.',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when these changes were made.',
  `creator_id` int NOT NULL COMMENT 'ID of the user who created the event',
  PRIMARY KEY (`id`),
  KEY `fk_model_index_creator_id` (`creator_id`),
  KEY `idx_model_index_model_id` (`model_id`),
  CONSTRAINT `fk_model_index_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_model_index_model_id` FOREIGN KEY (`model_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Used to keep track of which models have indexed columns.';
--;;
CREATE TABLE `model_index_value` (
  `model_index_id` int DEFAULT NULL COMMENT 'The ID of the indexed model.',
  `model_pk` bigint DEFAULT NULL,
  `name` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The label to display identifying the indexed value.',
  UNIQUE KEY `unique_model_index_value_model_index_id_model_pk` (`model_index_id`,`model_pk`),
  CONSTRAINT `fk_model_index_value_model_id` FOREIGN KEY (`model_index_id`) REFERENCES `model_index` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Used to keep track of the values indexed in a model';
--;;
CREATE TABLE `moderation_review` (
  `id` int NOT NULL AUTO_INCREMENT,
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'most recent modification time',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'creation time',
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'verified, misleading, confusing, not_misleading, pending',
  `text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `moderated_item_id` int NOT NULL COMMENT 'either a document or question ID; the item that needs review',
  `moderated_item_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'whether it''s a question or dashboard',
  `moderator_id` int NOT NULL COMMENT 'ID of the user who did the review',
  `most_recent` bit(1) NOT NULL COMMENT 'tag for most recent review',
  PRIMARY KEY (`id`),
  KEY `idx_moderation_review_item_type_item_id` (`moderated_item_type`,`moderated_item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Reviews (from moderators) for a given question/dashboard (BUCM)';
--;;
CREATE TABLE `native_query_snippet` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of the query snippet',
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `creator_id` int NOT NULL,
  `archived` bit(1) NOT NULL DEFAULT b'0',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `collection_id` int DEFAULT NULL COMMENT 'ID of the Snippet Folder (Collection) this Snippet is in, if any',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `template_tags` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Template tags for the snippet',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `fk_snippet_creator_id` (`creator_id`),
  KEY `idx_snippet_name` (`name`),
  KEY `idx_snippet_collection_id` (`collection_id`),
  CONSTRAINT `fk_snippet_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_snippet_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Query snippets (raw text) to be substituted in native queries';
--;;
CREATE TABLE `notification` (
  `id` int NOT NULL AUTO_INCREMENT,
  `payload_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'the type of the payload',
  `active` bit(1) NOT NULL DEFAULT b'1' COMMENT 'whether the notification is active',
  `created_at` timestamp(6) NOT NULL COMMENT 'The timestamp of when the notification was created',
  `updated_at` timestamp(6) NOT NULL COMMENT 'The timestamp of when the notification was updated',
  `internal_id` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'the internal id of the notification',
  `payload_id` int DEFAULT NULL COMMENT 'the internal id of the notification',
  `creator_id` int DEFAULT NULL COMMENT 'the id of the creator',
  PRIMARY KEY (`id`),
  UNIQUE KEY `internal_id` (`internal_id`),
  KEY `idx_notification_creator_id` (`creator_id`),
  KEY `idx_notification_payload_type_payload_id` (`payload_type`,`payload_id`),
  CONSTRAINT `fk_notification_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='join table that connect notification subscriptions and notification handlers';
--;;
CREATE TABLE `notification_card` (
  `id` int NOT NULL AUTO_INCREMENT,
  `card_id` int DEFAULT NULL COMMENT 'the card that the alert is connected to',
  `send_once` bit(1) NOT NULL DEFAULT b'0' COMMENT 'whether the alert should only run once',
  `send_condition` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'the condition of the alert',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the recipient was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the recipient was updated',
  `disable_links` bit(1) DEFAULT b'0' COMMENT 'Whether to disable alert email links',
  PRIMARY KEY (`id`),
  KEY `idx_notification_card_card_id` (`card_id`),
  CONSTRAINT `fk_notification_card_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Card related notifications';
--;;
CREATE TABLE `notification_handler` (
  `id` int NOT NULL AUTO_INCREMENT,
  `channel_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'the type of the channel, like :channel/email, :channel/slack',
  `notification_id` int NOT NULL COMMENT 'the notification that the handler is connected to',
  `channel_id` int DEFAULT NULL COMMENT 'the channel that the handler is connected to',
  `template_id` int DEFAULT NULL COMMENT 'the template that the handler is connected to',
  `active` bit(1) NOT NULL DEFAULT b'1' COMMENT 'whether the handler is active',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the handler was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the handler was updated',
  PRIMARY KEY (`id`),
  KEY `idx_notification_handler_notification_id` (`notification_id`),
  KEY `idx_notification_handler_channel_id` (`channel_id`),
  KEY `idx_notification_handler_template_id` (`template_id`),
  CONSTRAINT `fk_notification_handler_channel_id` FOREIGN KEY (`channel_id`) REFERENCES `channel` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_notification_handler_notification_id` FOREIGN KEY (`notification_id`) REFERENCES `notification` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_notification_handler_template_id` FOREIGN KEY (`template_id`) REFERENCES `channel_template` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='which channel to send the notification to';
--;;
CREATE TABLE `notification_recipient` (
  `id` int NOT NULL AUTO_INCREMENT,
  `notification_handler_id` int NOT NULL COMMENT 'the handler that the recipient is connected to',
  `type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'the type of the recipient',
  `user_id` int DEFAULT NULL COMMENT 'a user if the recipient has type user',
  `permissions_group_id` int DEFAULT NULL COMMENT 'a permissions group if the recipient has type permissions_group',
  `details` longtext COLLATE utf8mb4_unicode_ci COMMENT 'custom details for the recipient',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the recipient was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the recipient was updated',
  PRIMARY KEY (`id`),
  KEY `idx_notification_recipient_notification_handler_id` (`notification_handler_id`),
  KEY `idx_notification_recipient_user_id` (`user_id`),
  KEY `idx_notification_recipient_permissions_group_id` (`permissions_group_id`),
  CONSTRAINT `fk_notification_recipient_notification_handler_id` FOREIGN KEY (`notification_handler_id`) REFERENCES `notification_handler` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_notification_recipient_permissions_group_id` FOREIGN KEY (`permissions_group_id`) REFERENCES `permissions_group` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_notification_recipient_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='who should receive the notification';
--;;
CREATE TABLE `notification_subscription` (
  `id` int NOT NULL AUTO_INCREMENT,
  `notification_id` int NOT NULL COMMENT 'the notification that the subscription is connected to',
  `type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'the type of the subscription',
  `event_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'the event name of subscriptions with type :notification-subscription/system-event',
  `created_at` timestamp(6) NOT NULL COMMENT 'The timestamp of when the subscription was created',
  `cron_schedule` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'the cron schedule for the subscription',
  `ui_display_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'the display of the subscription, used for the UI only',
  PRIMARY KEY (`id`),
  KEY `idx_notification_subscription_notification_id` (`notification_id`),
  CONSTRAINT `fk_notification_subscription_notification_id` FOREIGN KEY (`notification_id`) REFERENCES `notification` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='which type of trigger a notification is subscribed to';
--;;
CREATE TABLE `oauth_access_token` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Auto-incrementing primary key',
  `token` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The access token string',
  `user_id` int DEFAULT NULL COMMENT 'FK to core_user.id (null for client_credentials)',
  `client_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The OAuth client_id',
  `scope` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON array of scopes',
  `expiry` bigint NOT NULL COMMENT 'Milliseconds since epoch',
  `resource` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of resource URIs',
  `revoked_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Null if active',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp of token creation',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_oauth_access_token_token` (`token`),
  KEY `idx_oauth_access_token_expiry` (`expiry`),
  KEY `idx_oauth_access_token_user_id` (`user_id`),
  CONSTRAINT `fk_oauth_access_token_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores access tokens for the embedded OAuth provider';
--;;
CREATE TABLE `oauth_authorization_code` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Auto-incrementing primary key',
  `code` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The authorization code string',
  `user_id` int NOT NULL COMMENT 'FK to core_user.id',
  `client_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The OAuth client_id',
  `redirect_uri` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Redirect URI for this authorization',
  `scope` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON array of scope strings',
  `nonce` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OIDC nonce value',
  `expiry` bigint NOT NULL COMMENT 'Milliseconds since epoch',
  `code_challenge` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PKCE code challenge',
  `code_challenge_method` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PKCE code challenge method',
  `resource` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of resource URIs (RFC 8707)',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp of code creation',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_oauth_authorization_code_code` (`code`),
  KEY `idx_oauth_authorization_code_expiry` (`expiry`),
  KEY `idx_oauth_authorization_code_user_id` (`user_id`),
  CONSTRAINT `fk_oauth_authorization_code_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores authorization codes for the embedded OAuth provider';
--;;
CREATE TABLE `oauth_client` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Auto-incrementing primary key',
  `client_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'OAuth client_id (UUID)',
  `client_secret_hash` longtext COLLATE utf8mb4_unicode_ci COMMENT 'PBKDF2 hash of client secret',
  `redirect_uris` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON array of redirect URIs',
  `grant_types` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON array of grant types',
  `response_types` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON array of response types',
  `scopes` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON array of scopes',
  `token_endpoint_auth_method` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OAuth token endpoint auth method (e.g. client_secret_basic)',
  `client_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Human-readable client name',
  `client_uri` longtext COLLATE utf8mb4_unicode_ci COMMENT 'URL of the client home page',
  `logo_uri` longtext COLLATE utf8mb4_unicode_ci COMMENT 'URL of the client logo image',
  `contacts` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of contact strings',
  `registration_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'static or dynamic',
  `client_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'confidential' COMMENT 'confidential or public',
  `application_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'web' COMMENT 'OAuth application type (web or native), defaults to web',
  `registration_access_token_hash` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Hashed RFC 7592 registration access token',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp of client registration',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp of last client update',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_oauth_client_client_id` (`client_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores OAuth2/OIDC client registrations for the embedded provider';
--;;
INSERT INTO `oauth_client` (`id`, `client_id`, `client_secret_hash`, `redirect_uris`, `grant_types`, `response_types`, `scopes`, `token_endpoint_auth_method`, `client_name`, `client_uri`, `logo_uri`, `contacts`, `registration_type`, `client_type`, `application_type`, `registration_access_token_hash`, `created_at`, `updated_at`) VALUES (1,'metabase-jwt-bearer',NULL,'[]','[\"urn:ietf:params:oauth:grant-type:jwt-bearer\"]','[]','[]','none','JWT bearer grant',NULL,NULL,NULL,'static','public','web',NULL,'2026-11-03 11:45:34.328391','2026-11-03 11:45:34.328391');
--;;
CREATE TABLE `oauth_client_event` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Auto-incrementing primary key',
  `oauth_client_id` int DEFAULT NULL COMMENT 'FK to oauth_client.id; nulled out if the client is deleted',
  `user_id` int DEFAULT NULL COMMENT 'FK to core_user.id of the user who made the decision; null for registration events',
  `event_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Event type: registered, approved, or denied',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp when the event occurred',
  PRIMARY KEY (`id`),
  KEY `idx_oauth_client_event_oauth_client_id` (`oauth_client_id`),
  KEY `idx_oauth_client_event_user_id` (`user_id`),
  CONSTRAINT `fk_oauth_client_event_oauth_client_id` FOREIGN KEY (`oauth_client_id`) REFERENCES `oauth_client` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_oauth_client_event_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Append-only audit log of dynamic client registration and authorization events';
--;;
CREATE TABLE `oauth_refresh_token` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Auto-incrementing primary key',
  `token` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The refresh token string',
  `user_id` int DEFAULT NULL COMMENT 'FK to core_user.id',
  `client_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The OAuth client_id',
  `scope` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON array of scopes',
  `resource` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of resource URIs',
  `expiry` bigint DEFAULT NULL COMMENT 'Milliseconds since epoch (null means no expiry)',
  `revoked_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Null if active',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp of token creation',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_oauth_refresh_token_token` (`token`),
  KEY `idx_oauth_refresh_token_user_id` (`user_id`),
  CONSTRAINT `fk_oauth_refresh_token_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores refresh tokens for the embedded OAuth provider';
--;;
CREATE TABLE `osi_ai_context` (
  `entity_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of entity this ai_context describes (table, card, measure, segment)',
  `entity_local_id` bigint NOT NULL COMMENT 'Local appdb id of the entity this ai_context describes',
  `ai_context` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'OSI ai_context JSON blob ({instructions, synonyms[], examples[]})',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the ai_context was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the ai_context was last updated',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  PRIMARY KEY (`entity_type`,`entity_local_id`),
  UNIQUE KEY `uq_osi_ai_context_entity_id` (`entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='OSI ai_context metadata for library entities, one row per entity';
--;;
CREATE TABLE `parameter_card` (
  `id` int NOT NULL AUTO_INCREMENT,
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'most recent modification time',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'creation time',
  `card_id` int NOT NULL COMMENT 'ID of the card generating the values',
  `parameterized_object_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of the entity consuming the values (dashboard, card, etc.)',
  `parameterized_object_id` int NOT NULL COMMENT 'ID of the entity consuming the values',
  `parameter_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_parameterized_object_card_parameter` (`parameterized_object_id`,`parameterized_object_type`,`parameter_id`),
  KEY `idx_parameter_card_parameterized_object_id` (`parameterized_object_id`),
  KEY `idx_parameter_card_card_id` (`card_id`),
  CONSTRAINT `fk_parameter_card_ref_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Join table connecting cards to entities (dashboards, other cards, etc.) that use the values generated by the card for filter values';
--;;
CREATE TABLE `permissions` (
