CREATE TABLE `query` (
  `query_hash` binary(32) NOT NULL COMMENT 'The hash of the query dictionary. (This is a 256-bit SHA3 hash of the query dict.)',
  `average_execution_time` int NOT NULL COMMENT 'Average execution time for the query, round to nearest number of milliseconds. This is updated as a rolling average.',
  `query` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`query_hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Information (such as average execution time) for different queries that have been previously ran.';
--;;
CREATE TABLE `query_action` (
  `action_id` int NOT NULL COMMENT 'The related action',
  `database_id` int NOT NULL,
  `dataset_query` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `legacy_query` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Legacy MBQL version of the query (serialized as JSON) for existing Query Actions created before v57, to support rollbacks to v56. This column should be removed in v58.',
  PRIMARY KEY (`action_id`),
  KEY `fk_query_action_database_id` (`database_id`),
  CONSTRAINT `fk_query_action_database_id` FOREIGN KEY (`database_id`) REFERENCES `metabase_database` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_query_action_ref_action_id` FOREIGN KEY (`action_id`) REFERENCES `action` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A readwrite query type of action';
--;;
CREATE TABLE `query_cache` (
  `query_hash` binary(32) NOT NULL COMMENT 'The hash of the query dictionary. (This is a 256-bit SHA3 hash of the query dict).',
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `results` longblob,
  `refresh_started_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When a process claimed the lease to recompute this expired entry; NULL when no refresh is in progress. Used to elect a single refresher across processes so the others serve stale results.',
  PRIMARY KEY (`query_hash`),
  KEY `idx_query_cache_updated_at` (`updated_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Cached results of queries are stored here when using the DB-based query cache.';
--;;
CREATE TABLE `query_execution` (
  `id` int NOT NULL AUTO_INCREMENT,
  `hash` binary(32) NOT NULL COMMENT 'The hash of the query dictionary. This is a 256-bit SHA3 hash of the query.',
  `started_at` timestamp(6) NULL DEFAULT NULL,
  `running_time` int NOT NULL COMMENT 'The time, in milliseconds, this query took to complete.',
  `result_rows` int NOT NULL COMMENT 'Number of rows in the query results.',
  `native` bit(1) NOT NULL COMMENT 'Whether the query was a native query, as opposed to an MBQL one (e.g., created with the GUI).',
  `context` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Short string specifying how this query was executed, e.g. in a Dashboard or Pulse.',
  `error` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `executor_id` int DEFAULT NULL COMMENT 'The ID of the User who triggered this query execution, if any.',
  `card_id` int DEFAULT NULL COMMENT 'The ID of the Card (Question) associated with this query execution, if any.',
  `dashboard_id` int DEFAULT NULL COMMENT 'The ID of the Dashboard associated with this query execution, if any.',
  `pulse_id` int DEFAULT NULL COMMENT 'The ID of the Pulse associated with this query execution, if any.',
  `database_id` int DEFAULT NULL COMMENT 'ID of the database this query was ran against.',
  `cache_hit` bit(1) DEFAULT NULL COMMENT 'Cache hit on query execution',
  `action_id` int DEFAULT NULL COMMENT 'The ID of the action associated with this query execution, if any.',
  `is_sandboxed` bit(1) DEFAULT NULL,
  `cache_hash` blob COMMENT 'Hash of normalized query, calculated in middleware.cache',
  `embedding_client` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Used by the embedding team to track SDK usage',
  `embedding_sdk_version` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parameterized` bit(1) DEFAULT NULL COMMENT 'Whether or not the query has parameters with non-nil values',
  `transform_id` int DEFAULT NULL COMMENT 'The ID of the Transform associated with this query execution, if any.',
  `lens_id` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The ID of the inspector lens associated with this query execution, if any.',
  `lens_params` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON-encoded parameters of the inspector lens associated with this query execution, if any.',
  `auth_method` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Authentication method used (e.g. jwt, saml, api-key, public, guest)',
  `tenant_id` int DEFAULT NULL COMMENT 'Tenant ID of the user who executed this query',
  `is_impersonated` bit(1) DEFAULT NULL COMMENT 'Whether the query was executed with connection impersonation',
  `is_db_routed` bit(1) DEFAULT NULL COMMENT 'Whether the query was routed to a destination database',
  `parameters` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON-encoded query parameters (filter values)',
  `embedding_hostname` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Hostname from Origin header, PII',
  `embedding_path` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path from Referer header (query params stripped), PII',
  `user_agent` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-Agent header, PII',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client IP address, PII',
  `sanitized_user_agent` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Human-friendly parsed User-Agent (e.g. Browser (Chrome/Windows)), PII',
  `embedding_route` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'API route surface (e.g. public, guest-embed, metabot, agent-api)',
  `metabase_version` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Metabase server version tag at time of insert',
  `embedding_client_identifier` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Identifier of the concrete embedding client (e.g. the data-app name) from the X-Metabase-Client-Identifier header',
  `sandbox_details` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array describing the sandboxes (row-level restrictions) applied to this execution',
  PRIMARY KEY (`id`),
  KEY `idx_query_execution_started_at` (`started_at`),
  KEY `idx_query_execution_query_hash_started_at` (`hash`,`started_at`),
  KEY `idx_query_execution_card_id` (`card_id`),
  KEY `idx_query_execution_card_id_started_at` (`card_id`,`started_at`),
  KEY `idx_query_execution_executor_id` (`executor_id`),
  KEY `idx_query_execution_context` (`context`),
  KEY `idx_query_execution_action_id` (`action_id`),
  KEY `idx_query_execution_transform_id` (`transform_id`),
  KEY `idx_query_execution_tenant_id` (`tenant_id`),
  KEY `idx_query_execution_card_qualified_id` ((concat(_utf8mb4'card_',`card_id`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A log of executed queries, used for calculating historic execution times, auditing, and other purposes.';
--;;
CREATE TABLE `query_field` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'PK',
  `card_id` int NOT NULL COMMENT 'referenced card',
  `field_id` int DEFAULT NULL,
  `explicit_reference` bit(1) DEFAULT b'1',
  `column` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'name of the table or card being referenced',
  `table` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `table_id` int DEFAULT NULL COMMENT 'track the table directly, in case the field does not exist',
  `schema` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'name of the schema of the table being referenced',
  PRIMARY KEY (`id`),
  KEY `idx_query_field_card_id` (`card_id`),
  KEY `idx_query_field_field_id` (`field_id`),
  CONSTRAINT `fk_query_field_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_query_field_field_id` FOREIGN KEY (`field_id`) REFERENCES `metabase_field` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Fields used by a card''s query';
--;;
CREATE TABLE `query_table` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'PK',
  `card_id` int NOT NULL COMMENT 'referenced card',
  `table_id` int DEFAULT NULL COMMENT 'referenced field',
  `schema` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'name of the schema of the table being referenced',
  `table` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'name of the table or card being referenced',
  PRIMARY KEY (`id`),
  KEY `idx_query_table_card_id` (`card_id`),
  KEY `idx_query_table_table_id` (`table_id`),
  CONSTRAINT `fk_query_table_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_query_table_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tables used by a card''s query';
--;;
CREATE TABLE `queue_message_outbox` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `queue_name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The name of the queue this batch will be published to',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the row was written to the outbox',
  `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON-encoded payload (one stored batch)',
  `publish_attempts` int NOT NULL DEFAULT '0' COMMENT 'Number of consecutive times the recovery sweep has failed to publish this row. Drives the exponential backoff between recovery attempts; the row is never dropped (it is retried until it publishes).',
  `next_attempt_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Earliest time the recovery sweep may retry this row after a failed publish (now + exponential backoff). Null until the first failure; until then the sweep gates on created_at instead.',
  PRIMARY KEY (`id`),
  KEY `idx_queue_message_outbox_created_at` (`created_at`),
  KEY `idx_queue_message_outbox_next_attempt_at` (`next_attempt_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Transactional outbox for queue publishes. Rows are inserted inside the business transaction (before-commit) and handed to the queue backend after it commits, so a message is published iff the transaction that produced it commits. A recovery job republishes any rows a crash left behind.';
--;;
CREATE TABLE `recent_views` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT 'The user associated with this view',
  `model` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The name of the model that was viewed',
  `model_id` int NOT NULL COMMENT 'The ID of the model that was viewed',
  `timestamp` timestamp(6) NOT NULL,
  `context` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'view' COMMENT 'The contextual action that netted a recent view.',
  PRIMARY KEY (`id`),
  KEY `idx_recent_views_user_id` (`user_id`),
  KEY `idx_recent_views_model_model_id` (`model`,`model_id`),
  CONSTRAINT `fk_recent_views_ref_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Used to store recently viewed objects for each user';
--;;
CREATE TABLE `remote_sync_object` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key identifier for remote-sync objects',
  `model_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of model',
  `model_id` int NOT NULL COMMENT 'ID of the model',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Status of the object',
  `status_changed_at` timestamp(6) NOT NULL COMMENT 'When the status changed',
  `model_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `model_collection_id` int DEFAULT NULL COMMENT 'Copy of the collection from the object being sync''ed',
  `model_display` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Copy of the display field from the object being sync''ed',
  `model_table_id` int DEFAULT NULL COMMENT 'Parent table ID for Field/Segment/Table models',
  `model_table_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Parent table name for Field/Segment/Table models',
  `file_path` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Repo-relative path of this entity''s serialized file as of the last export; used to resolve old paths for incremental renames/deletes',
  `content_hash` longtext COLLATE utf8mb4_unicode_ci COMMENT 'SHA-256 (hex) of this entity''s serialized YAML as of the last sync or null for no last sync.',
  PRIMARY KEY (`id`),
  KEY `idx_remote_sync_object_model_lookup` (`model_type`,`model_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Track remote sync objects';
--;;
CREATE TABLE `remote_sync_task` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sync_task_type` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of the sync task',
  `progress` float DEFAULT NULL COMMENT 'Progress percentage of the sync task (0.0 to 1.0)',
  `cancelled` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the sync task was cancelled',
  `started_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp when the sync task started',
  `ended_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Timestamp when the sync task ended',
  `last_progress_report_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp of the last progress update',
  `initiated_by` int DEFAULT NULL COMMENT 'ID of the user who initiated the sync task',
  `error_message` longtext COLLATE utf8mb4_unicode_ci COMMENT 'error message if this task failed',
  `version` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Version that was imported or exported (ex the Git SHA)',
  `conflicts` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON serialized list of conflicts detected during import',
  `outcome` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON describing the task outcome (kind plus counts/branch), rendered to a localized confirmation message in the UI',
  `last_heartbeat_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Heartbeat timestamp stamped periodically while the task runs; a stale value means the owning process died. Null before the first beat.',
  PRIMARY KEY (`id`),
  KEY `idx_remote_sync_task_initiated_by` (`initiated_by`),
  KEY `idx_remote_sync_task_current` (`started_at` DESC,`id` DESC),
  KEY `idx_remote_sync_task_progress_report` (`last_progress_report_at`),
  CONSTRAINT `fk_remote_sync_task_initiated_by` FOREIGN KEY (`initiated_by`) REFERENCES `core_user` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to track remote sync tasks and their progress';
--;;
CREATE TABLE `report_card` (
  `id` int NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `display` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `dataset_query` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `visualization_settings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `creator_id` int NOT NULL,
  `database_id` int NOT NULL,
  `table_id` int DEFAULT NULL,
  `query_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `archived` bit(1) NOT NULL DEFAULT b'0',
  `collection_id` int DEFAULT NULL COMMENT 'Optional ID of Collection this Card belongs to.',
  `public_uuid` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `made_public_by_id` int DEFAULT NULL COMMENT 'The ID of the User who first publically shared this Card.',
  `enable_embedding` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Is this Card allowed to be embedded in different websites (using a signed JWT)?',
  `embedding_params` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `cache_ttl` int DEFAULT NULL COMMENT 'The maximum time, in seconds, to return cached results for this Card rather than running a new query.',
  `result_metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `collection_position` smallint DEFAULT NULL COMMENT 'Optional pinned position for this item in its Collection. NULL means item is not pinned.',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `parameters` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'List of parameter associated to a card',
  `parameter_mappings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'List of parameter associated to a card',
  `collection_preview` bit(1) NOT NULL DEFAULT b'1',
  `metabase_version` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Metabase version used to create the card.',
  `type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'question' COMMENT 'The type of card, could be ''question'', ''model'', ''metric''',
  `initially_published_at` timestamp(6) NULL DEFAULT NULL COMMENT 'The timestamp when the card was first published in a static embed',
  `cache_invalidated_at` timestamp(6) NULL DEFAULT NULL COMMENT 'An invalidation time that can supersede cache_config.invalidated_at',
  `last_used_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `view_count` int NOT NULL DEFAULT '0' COMMENT 'Keeps a running count of card views',
  `archived_directly` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Was this thing trashed directly',
  `dataset_query_metrics_v2_migration_backup` longtext COLLATE utf8mb4_unicode_ci COMMENT 'The copy of dataset_query before the metrics v2 migration',
  `source_card_id` int DEFAULT NULL COMMENT 'The ID of the model or question this card is based on',
  `dashboard_id` int DEFAULT NULL COMMENT 'The dashboard that owns the card, if it is a dashboard-internal card.',
  `card_schema` int NOT NULL DEFAULT '20' COMMENT 'Arbitrary revision number for how we store queries in report_card',
  `document_id` int DEFAULT NULL COMMENT 'Associates cards with a particular document',
  `legacy_query` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Legacy MBQL version of the query (serialized as JSON) for existing Cards created before v57, to support rollbacks to v56. This column should be removed in v58.',
  `embedding_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The type of embedding for this card',
  `public_uuid_prefix` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Plaintext leading characters of public_uuid, used as an indexed narrowing key for public-link lookups.',
  `dimensions` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of persisted dimension definitions (id, display-name, types)',
  `dimension_mappings` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of dimension-to-field mappings (dimension-id, target, table-id)',
  `metabot_conversation_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The Metabot conversation this card was saved from; NULL when not AI-generated or after the conversation is trimmed',
  `metabot_chart_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The generated chart id within the Metabot conversation this card was saved from; used to match the card back to its inline chart',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  UNIQUE KEY `public_uuid` (`public_uuid`),
  KEY `idx_card_creator_id` (`creator_id`),
  KEY `idx_card_collection_id` (`collection_id`),
  KEY `idx_card_public_uuid` (`public_uuid`),
  KEY `fk_card_made_public_by_id` (`made_public_by_id`),
  KEY `fk_report_card_ref_database_id` (`database_id`),
  KEY `fk_report_card_ref_table_id` (`table_id`),
  KEY `idx_report_card_source_card_id` (`source_card_id`),
  KEY `idx_report_card_dashboard_id` (`dashboard_id`),
  KEY `idx_report_card_card_schema` (`card_schema`),
  KEY `idx_report_card_type` (`type`),
  KEY `idx_repord_card_document_id` (`document_id`),
  KEY `idx_report_card_public_uuid_prefix` (`public_uuid_prefix`),
  KEY `idx_report_card_metabot_conversation_id` (`metabot_conversation_id`),
  CONSTRAINT `fk_card_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_card_made_public_by_id` FOREIGN KEY (`made_public_by_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_card_ref_user_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_report_card_document_id` FOREIGN KEY (`document_id`) REFERENCES `document` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_report_card_metabot_conversation_id` FOREIGN KEY (`metabot_conversation_id`) REFERENCES `metabot_conversation` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_report_card_ref_dashboard_id` FOREIGN KEY (`dashboard_id`) REFERENCES `report_dashboard` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_report_card_ref_database_id` FOREIGN KEY (`database_id`) REFERENCES `metabase_database` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_report_card_ref_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_report_card_source_card_id_ref_report_card_id` FOREIGN KEY (`source_card_id`) REFERENCES `report_card` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `report_cardfavorite` (
  `id` int NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL,
  `updated_at` timestamp(6) NOT NULL,
  `card_id` int NOT NULL,
  `owner_id` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_cardfavorite_card_id_owner_id` (`card_id`,`owner_id`),
  KEY `idx_cardfavorite_card_id` (`card_id`),
  KEY `idx_cardfavorite_owner_id` (`owner_id`),
  CONSTRAINT `fk_cardfavorite_ref_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cardfavorite_ref_user_id` FOREIGN KEY (`owner_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `report_dashboard` (
  `id` int NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL,
  `updated_at` timestamp(6) NOT NULL,
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `creator_id` int NOT NULL,
  `parameters` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `points_of_interest` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `caveats` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `show_in_getting_started` bit(1) NOT NULL DEFAULT b'0',
  `public_uuid` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `made_public_by_id` int DEFAULT NULL COMMENT 'The ID of the User who first publically shared this Dashboard.',
  `enable_embedding` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Is this Dashboard allowed to be embedded in different websites (using a signed JWT)?',
  `embedding_params` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `archived` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Is this Dashboard archived (effectively treated as deleted?)',
  `position` int DEFAULT NULL COMMENT 'The position this Dashboard should appear in the Dashboards list, lower-numbered positions appearing before higher numbered ones.',
  `collection_id` int DEFAULT NULL COMMENT 'Optional ID of Collection this Dashboard belongs to.',
  `collection_position` smallint DEFAULT NULL COMMENT 'Optional pinned position for this item in its Collection. NULL means item is not pinned.',
  `cache_ttl` int DEFAULT NULL COMMENT 'Granular cache TTL for specific dashboard.',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `auto_apply_filters` bit(1) NOT NULL DEFAULT b'1',
  `width` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'fixed',
  `initially_published_at` timestamp(6) NULL DEFAULT NULL COMMENT 'The timestamp when the dashboard was first published in a static embed',
  `view_count` int NOT NULL DEFAULT '0' COMMENT 'Keeps a running count of dashboard views',
  `archived_directly` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Was this thing trashed directly',
  `last_viewed_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Timestamp of when this dashboard was last viewed',
  `embedding_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The type of embedding for this dashboard',
  `public_uuid_prefix` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Plaintext leading characters of public_uuid, used as an indexed narrowing key for public-link lookups.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  UNIQUE KEY `public_uuid` (`public_uuid`),
  KEY `idx_dashboard_creator_id` (`creator_id`),
  KEY `idx_report_dashboard_show_in_getting_started` (`show_in_getting_started`),
  KEY `idx_dashboard_public_uuid` (`public_uuid`),
  KEY `idx_dashboard_collection_id` (`collection_id`),
  KEY `fk_dashboard_made_public_by_id` (`made_public_by_id`),
  KEY `idx_report_dashboard_public_uuid_prefix` (`public_uuid_prefix`),
  CONSTRAINT `fk_dashboard_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_dashboard_made_public_by_id` FOREIGN KEY (`made_public_by_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_dashboard_ref_user_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `report_dashboardcard` (
  `id` int NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `size_x` int,
  `size_y` int,
  `row` int NOT NULL,
  `col` int NOT NULL,
  `card_id` int DEFAULT NULL,
  `dashboard_id` int NOT NULL,
  `parameter_mappings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `visualization_settings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `action_id` int DEFAULT NULL COMMENT 'The related action',
  `dashboard_tab_id` int DEFAULT NULL COMMENT 'The referenced tab id that dashcard is on, it''s nullable for dashboard with no tab',
  `inline_parameters` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of parameter IDs that should be displayed inline with this card',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_dashboardcard_card_id` (`card_id`),
  KEY `idx_dashboardcard_dashboard_id` (`dashboard_id`),
  KEY `fk_report_dashboardcard_ref_action_id` (`action_id`),
  KEY `fk_report_dashboardcard_ref_dashboard_tab_id` (`dashboard_tab_id`),
  CONSTRAINT `fk_dashboardcard_ref_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_dashboardcard_ref_dashboard_id` FOREIGN KEY (`dashboard_id`) REFERENCES `report_dashboard` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_report_dashboardcard_ref_action_id` FOREIGN KEY (`action_id`) REFERENCES `action` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_report_dashboardcard_ref_dashboard_tab_id` FOREIGN KEY (`dashboard_tab_id`) REFERENCES `dashboard_tab` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `result_metadata_status` (
  `id` int NOT NULL AUTO_INCREMENT,
  `entity_type` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The type of the entity',
  `entity_id` int NOT NULL COMMENT 'The ID of the entity',
  `stale` int NOT NULL DEFAULT '0' COMMENT 'How many writes changed what the job reads for the entity since the job last read it; the job processes it while above 0',
  `fail_count` int NOT NULL DEFAULT '0' COMMENT 'How many times in a row the job failed to process the entity since a write changed it',
  `terminal` bit(1) NOT NULL DEFAULT b'0' COMMENT 'True when the job gave up on the entity after its failures, until a write changes it',
  `analysis_version` int NOT NULL COMMENT 'The version of the result metadata logic that last processed the card',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_result_metadata_status` (`entity_type`,`entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Whether the result metadata of each MBQL card is to be re-derived';
--;;
CREATE TABLE `revision` (
  `id` int NOT NULL AUTO_INCREMENT,
  `model` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `model_id` int NOT NULL,
  `user_id` int NOT NULL,
  `timestamp` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `object` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `is_reversion` bit(1) NOT NULL DEFAULT b'0',
  `is_creation` bit(1) NOT NULL DEFAULT b'0',
  `message` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `most_recent` bit(1) NOT NULL DEFAULT b'0',
  `metabase_version` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Metabase version used to create the revision.',
  PRIMARY KEY (`id`),
  KEY `idx_revision_model_model_id` (`model`,`model_id`),
  KEY `fk_revision_ref_user_id` (`user_id`),
  KEY `idx_revision_most_recent` (`most_recent`),
  CONSTRAINT `fk_revision_ref_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `sandboxes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `group_id` int NOT NULL COMMENT 'ID of the Permissions Group this policy affects.',
  `table_id` int NOT NULL COMMENT 'ID of the Table that should get automatically replaced as query source for the Permissions Group.',
  `card_id` int DEFAULT NULL,
  `attribute_remappings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_gtap_table_id_group_id` (`table_id`,`group_id`),
  KEY `fk_gtap_group_id` (`group_id`),
  KEY `idx_gtap_table_id_group_id` (`table_id`,`group_id`),
  KEY `fk_gtap_card_id` (`card_id`),
  CONSTRAINT `fk_gtap_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_gtap_group_id` FOREIGN KEY (`group_id`) REFERENCES `permissions_group` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_gtap_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Records that a given Card (Question) should automatically replace a given Table as query source for a given a Perms Group.';
--;;
CREATE TABLE `search_index_metadata` (
  `id` int NOT NULL AUTO_INCREMENT,
  `engine` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The kind of search engine which this index belongs to.',
  `version` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Used to determine metabase compatibility. Format may depend on engine in future.',
  `index_name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The name by which the given engine refers to this particular index, e.g. table name.',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'One of ''pending'', ''active'', or ''retired''',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the index was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the index status was updated',
  `lang_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'en' COMMENT 'Language code the data in the index is in',
  PRIMARY KEY (`id`),
  UNIQUE KEY `index_name` (`index_name`),
  UNIQUE KEY `idx_search_index_metadata_unique_status` (`engine`,`version`,`lang_code`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Each entry corresponds to some queryable index, and contains metadata about it.';
--;;
CREATE TABLE `secret` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Part of composite primary key for secret; this is the uniquely generted ID column',
  `version` int NOT NULL DEFAULT '1' COMMENT 'Part of composite primary key for secret; this is the version column',
  `creator_id` int DEFAULT NULL COMMENT 'User ID who created this secret instance',
  `created_at` timestamp(6) NOT NULL COMMENT 'Timestamp for when this secret instance was created',
  `updated_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Timestamp for when this secret record was updated. Only relevant when non-value field changes since a value change will result in a new version being inserted.',
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The name of this secret record.',
  `kind` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The kind of secret this record represents; the value is interpreted as a Clojure keyword with a hierarchy. Ex: ''bytes'' means generic binary data, ''jks-keystore'' extends ''bytes'' but has a specific meaning.',
  `source` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The source of secret record, which controls how Metabase interprets the value (ex: ''file-path'' means the ''simple_value'' is not the real value, but a pointer to a file that contains the value).',
  `value` longblob,
  PRIMARY KEY (`id`,`version`),
  KEY `fk_secret_ref_user_id` (`creator_id`),
  CONSTRAINT `fk_secret_ref_user_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Storage for managed secrets (passwords, binary data, etc.)';
--;;
CREATE TABLE `security_advisory` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Auto-incrementing primary key',
  `advisory_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Unique advisory identifier (e.g. SC-2026-001)',
  `severity` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Severity level: critical, high, medium, or low',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Human-readable advisory title',
  `description` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Short summary of the advisory',
  `advisory_url` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Link to the full advisory',
  `remediation` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Remediation instructions',
  `affected_versions` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON array of {min, fixed} version ranges',
  `matching_query` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON HoneySQL query keyed by dialect (null = affects all instances)',
  `published_at` timestamp(6) NOT NULL COMMENT 'When the advisory was published',
  `fetched_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When Metabase fetched this advisory',
  `match_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Status: active, resolved, not_affected, or error',
  `last_evaluated_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Last time the matching query was evaluated',
  `acknowledged_by` int DEFAULT NULL COMMENT 'FK to core_user.id — admin who acknowledged the advisory',
  `acknowledged_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When the advisory was acknowledged',
  `last_notified_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When the last notification was sent for this advisory',
  `updated_at` timestamp(6) NOT NULL COMMENT 'When the advisory was last updated upstream (used as sync cursor)',
  `download_jar_urls` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of {version, url} downloadable JARs',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_security_advisory_advisory_id` (`advisory_id`),
  KEY `idx_security_advisory_acknowledged_by` (`acknowledged_by`),
  KEY `idx_security_advisory_match_status` (`match_status`),
  CONSTRAINT `fk_security_advisory_acknowledged_by` FOREIGN KEY (`acknowledged_by`) REFERENCES `core_user` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores security advisories fetched from the advisory feed';
--;;
CREATE TABLE `segment` (
  `id` int NOT NULL AUTO_INCREMENT,
  `table_id` int NOT NULL,
  `creator_id` int NOT NULL,
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `archived` bit(1) DEFAULT b'0',
  `definition` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp(6) NOT NULL,
  `updated_at` timestamp(6) NOT NULL,
  `points_of_interest` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `caveats` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `show_in_getting_started` bit(1) NOT NULL DEFAULT b'0',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_segment_creator_id` (`creator_id`),
  KEY `idx_segment_table_id` (`table_id`),
  KEY `idx_segment_show_in_getting_started` (`show_in_getting_started`),
  CONSTRAINT `fk_segment_ref_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_segment_ref_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `semantic_search_token_tracking` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID of a request',
  `model_name` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of model used for embeddings generation',
  `request_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Type of request, possibly index or query',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Datetime of insertion',
  `total_tokens` int NOT NULL COMMENT 'Total tokens value as per OpenAI compatible API',
  PRIMARY KEY (`id`),
  KEY `idx_semantic_search_token_tracking_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Token usage tracking info for semantic search';
--;;
CREATE TABLE `sequences` (
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The name of the sequence',
  `next_val` bigint NOT NULL COMMENT 'The next value in this sequence',
  PRIMARY KEY (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A table for generating atomic sequence numbers';
--;;
CREATE TABLE `setting` (
  `key` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `value_with_aad` longtext COLLATE utf8mb4_unicode_ci COMMENT 'The setting''s value, encrypted under additional authenticated data naming the setting',
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `source_dimension_daily` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `source_type` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Owning source kind for the dimension fact',
  `source_id` int NOT NULL COMMENT 'Owning table or card ID for the dimension fact',
  `ownership_mode` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ownership attribution mode for the dimension fact',
  `field_id` int NOT NULL COMMENT 'Breakout field referenced by the dimension fact',
  `temporal_unit` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Temporal bucketing unit for temporal breakouts when applicable',
  `binning` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Canonical serialized binning configuration when applicable',
  `bucket_date` date NOT NULL COMMENT 'UTC day covered by the rollup row',
  `count` int NOT NULL COMMENT 'Number of observations for this fact on the bucket day',
  PRIMARY KEY (`id`),
  KEY `idx_source_dimension_daily_bucket_source` (`bucket_date`,`source_type`,`source_id`,`ownership_mode`),
  KEY `idx_source_dimension_daily_field` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily source-scoped dimension usage rollups';
--;;
CREATE TABLE `source_dimension_profile_daily` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `source_type` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Owning source kind for the profiled dimension',
  `source_id` int NOT NULL COMMENT 'Owning table or card ID for the profiled dimension',
  `field_id` int NOT NULL COMMENT 'Field being profiled',
  `source_basis` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Provenance of the profile signal such as fingerprint',
  `observation_type` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Kind of profile observation such as single-value or all-null',
  `observation_value` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Optional serialized value associated with the profile observation',
  `bucket_date` date NOT NULL COMMENT 'UTC day when the profile observation was recorded',
  `count` int NOT NULL COMMENT 'Number of times the observation was recorded on the bucket day',
  PRIMARY KEY (`id`),
  KEY `idx_source_dimension_profile_daily_bucket_source` (`bucket_date`,`source_type`,`source_id`),
  KEY `idx_source_dimension_profile_daily_field` (`field_id`,`observation_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily source-scoped dimension profile observations';
--;;
CREATE TABLE `source_metric_daily` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `source_type` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Owning source kind for direct or projected facts, or null for canonical mixed facts',
  `source_id` int DEFAULT NULL COMMENT 'Owning table or card ID for direct or projected facts, or null for canonical mixed facts',
  `ownership_mode` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ownership attribution mode such as direct, projected, or mixed',
  `agg_type` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Aggregation operator for the metric fact',
  `agg_field_id` int DEFAULT NULL COMMENT 'Aggregated field referenced by the metric fact when applicable',
  `temporal_field_id` int DEFAULT NULL COMMENT 'Breakout field supplying temporal context for the metric fact when applicable',
  `temporal_unit` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Temporal bucketing unit associated with the metric fact when applicable',
  `bucket_date` date NOT NULL COMMENT 'UTC day covered by the rollup row',
  `count` int NOT NULL COMMENT 'Number of observations for this fact on the bucket day',
  PRIMARY KEY (`id`),
  KEY `idx_source_metric_daily_bucket_source` (`bucket_date`,`source_type`,`source_id`,`ownership_mode`),
  KEY `idx_source_metric_daily_agg` (`agg_type`,`agg_field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily source-scoped metric usage rollups';
--;;
CREATE TABLE `source_replacement_run` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `source_entity_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of the source entity (card or table)',
  `source_entity_id` int NOT NULL COMMENT 'ID of the source entity',
  `target_entity_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of the target entity (card or table)',
  `target_entity_id` int NOT NULL COMMENT 'ID of the target entity',
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Current status (started, succeeded, failed, canceled, timeout)',
  `is_active` bit(1) DEFAULT NULL COMMENT 'True only for currently running replacements, null for completed',
  `progress` float DEFAULT NULL COMMENT 'Progress from 0.0 to 1.0',
  `message` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Human-readable message; may contain error info',
  `user_id` int DEFAULT NULL COMMENT 'User who initiated the replacement',
  `start_time` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the replacement started',
  `end_time` timestamp(6) NULL DEFAULT NULL COMMENT 'When the replacement completed (null if still running)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_active_source_replacement_run` (`is_active`),
  KEY `idx_source_replacement_run_user_id` (`user_id`),
  KEY `idx_source_replacement_run_source_entity` (`source_entity_type`,`source_entity_id`),
  KEY `idx_source_replacement_run_target_entity` (`target_entity_type`,`target_entity_id`),
  CONSTRAINT `fk_source_replacement_run_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to track source replacement executions and their status';
--;;
CREATE TABLE `source_segment_composite_daily` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `source_type` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Owning source kind for direct or projected facts, or null for canonical mixed facts',
  `source_id` int DEFAULT NULL COMMENT 'Owning table or card ID for direct or projected facts, or null for canonical mixed facts',
  `ownership_mode` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ownership attribution mode such as direct, projected, or mixed',
  `clause` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Canonical serialized representation of the whole :and filter clause',
  `atom_fingerprints` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Sorted JSON array of canonical serialized atom clauses contained in the basket',
  `atom_count` int NOT NULL COMMENT 'Number of atomic predicates in the basket',
  `bucket_date` date NOT NULL COMMENT 'UTC day covered by the rollup row',
  `count` int NOT NULL COMMENT 'Number of observations for this composite fact on the bucket day',
  PRIMARY KEY (`id`),
  KEY `idx_source_segment_composite_daily_bucket_source` (`bucket_date`,`source_type`,`source_id`,`ownership_mode`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily source-scoped composite segment usage rollups (whole :and baskets)';
--;;
CREATE TABLE `source_segment_daily` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `source_type` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Owning source kind for direct or projected facts, or null for canonical mixed facts',
  `source_id` int DEFAULT NULL COMMENT 'Owning table or card ID for direct or projected facts, or null for canonical mixed facts',
  `ownership_mode` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ownership attribution mode such as direct, projected, or mixed',
  `field_id` int DEFAULT NULL COMMENT 'Field referenced by the segment fact when applicable',
  `predicate` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Canonical serialized representation of the atomic segment predicate',
  `bucket_date` date NOT NULL COMMENT 'UTC day covered by the rollup row',
  `count` int NOT NULL COMMENT 'Number of observations for this fact on the bucket day',
  PRIMARY KEY (`id`),
  KEY `idx_source_segment_daily_bucket_source` (`bucket_date`,`source_type`,`source_id`,`ownership_mode`),
  KEY `idx_source_segment_daily_field` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily source-scoped segment usage rollups';
--;;
CREATE TABLE `sso_relay_state` (
  `id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA-512 hash of the RelayState key',
  `continue_url` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'URL the popup falls back to when there is no opener window',
  `origin` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Origin used as the postMessage target when handing the session back to the opener (embedding only)',
  `embedding` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether this is a modular-embedding popup login (postMessage handback) vs. a regular redirect login',
  `expires_at` timestamp(6) NOT NULL COMMENT 'When this RelayState entry expires and is no longer valid',
  `created_at` timestamp(6) NOT NULL COMMENT 'When this RelayState entry was created',
  PRIMARY KEY (`id`),
  KEY `idx_sso_relay_state_expires_at` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Server-side store for SAML SSO RelayState context';
--;;
CREATE TABLE `stored_result` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `result_data` blob NOT NULL COMMENT 'gzipped+nippy serialized query result bytes',
  `creator_id` int DEFAULT NULL COMMENT 'User who produced this snapshot. Used for the can-read? bypass and for the data-permission gate (sandboxing/impersonation) applied to non-creator readers.',
  `database_id` int DEFAULT NULL COMMENT 'Database the snapshot was produced against. Used by the data-permission gate without needing to parse `dataset_query`. NULL when the snapshot isn''t tied to a database (e.g. a synthetic chart).',
  `dataset_query` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `data_access_token` longtext COLLATE utf8mb4_unicode_ci COMMENT 'EDN-encoded effective-data-access token (sandbox/impersonation/routing fingerprint) for the creator''s lens this snapshot was computed under. Compared against a viewer''s token to gate cached reads. NULL means creator+admin only.',
  `row_count` int DEFAULT NULL COMMENT 'Number of rows in the snapshot',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the snapshot was written',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the snapshot was last updated',
  PRIMARY KEY (`id`),
  KEY `idx_stored_result_creator_id` (`creator_id`),
  KEY `idx_stored_result_database_id` (`database_id`),
  CONSTRAINT `fk_stored_result_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_stored_result_database_id` FOREIGN KEY (`database_id`) REFERENCES `metabase_database` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Cached query result snapshots referenced by static `cardEmbed` nodes in documents. Decoupled from any one feature so future tools can write static charts without going through explorations.';
--;;
CREATE TABLE `stored_result_use` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `stored_result_id` int NOT NULL COMMENT 'The cached snapshot this row references',
  `exploration_id` int DEFAULT NULL COMMENT 'The referencing exploration',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the reference was recorded',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the reference row was last updated',
  `card_id` int DEFAULT NULL COMMENT 'The referencing Card',
  PRIMARY KEY (`id`),
  KEY `idx_stored_result_use_stored_result_id` (`stored_result_id`),
  KEY `idx_stored_result_use_exploration_id` (`exploration_id`),
  KEY `idx_stored_result_use_card_id` (`card_id`),
  CONSTRAINT `fk_stored_result_use_card_id` FOREIGN KEY (`card_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_stored_result_use_exploration_id` FOREIGN KEY (`exploration_id`) REFERENCES `exploration` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_stored_result_use_stored_result_id` FOREIGN KEY (`stored_result_id`) REFERENCES `stored_result` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Records each reference to a stored_result snapshot.';
--;;
CREATE TABLE `support_access_grant_log` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique identifier for the grant',
  `user_id` int DEFAULT NULL COMMENT 'ID of the admin user who created this grant',
  `ticket_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Support ticket number associated with this grant',
  `notes` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Additional notes associated with this grant',
  `grant_start_timestamp` timestamp(6) NOT NULL COMMENT 'When the grant becomes active (UTC)',
  `grant_end_timestamp` timestamp(6) NOT NULL COMMENT 'When the grant expires (UTC)',
  `revoked_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When the grant was manually revoked (UTC), null if not revoked',
  `revoked_by_user_id` int DEFAULT NULL COMMENT 'ID of the admin user who revoked this grant',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When this record was created (UTC)',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When this record was last updated (UTC)',
  PRIMARY KEY (`id`),
  KEY `idx_support_access_grant_log_user_id` (`user_id`),
  KEY `idx_support_access_grant_log_revoked_by_user_id` (`revoked_by_user_id`),
  KEY `idx_support_access_grant_log_active` (`grant_end_timestamp`,`revoked_at`),
  CONSTRAINT `fk_support_access_grant_log_revoked_by_user_id` FOREIGN KEY (`revoked_by_user_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_support_access_grant_log_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Store support access grant requests and their lifecycle for audit purposes';
--;;
CREATE TABLE `table_privileges` (
  `table_id` int NOT NULL COMMENT 'Table ID',
  `role` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Role name. NULL indicates the privileges are the current user''s',
  `select` bit(1) NOT NULL DEFAULT b'0',
  `update` bit(1) NOT NULL DEFAULT b'0',
  `insert` bit(1) NOT NULL DEFAULT b'0',
  `delete` bit(1) NOT NULL DEFAULT b'0',
  KEY `fk_table_privileges_table_id` (`table_id`),
  KEY `idx_table_privileges_role` (`role`),
  CONSTRAINT `fk_table_privileges_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table for user and role privileges by table';
--;;
CREATE TABLE `task_history` (
  `id` int NOT NULL AUTO_INCREMENT,
  `task` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of the task',
  `db_id` int DEFAULT NULL,
  `started_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `ended_at` timestamp(6) NULL DEFAULT NULL,
  `duration` int DEFAULT NULL,
  `task_details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status` varchar(21) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'started' COMMENT 'the status of task history, could be started, failed, success, unknown',
  `run_id` int DEFAULT NULL COMMENT 'FK to task_run - groups tasks belonging to the same run',
  `logs` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON array of captured log messages during task execution',
  PRIMARY KEY (`id`),
  KEY `idx_task_history_end_time` (`ended_at`),
  KEY `idx_task_history_db_id` (`db_id`),
  KEY `idx_task_history_started_at` (`started_at`),
  KEY `idx_task_history_run_id` (`run_id`),
  CONSTRAINT `fk_task_history_run_id` FOREIGN KEY (`run_id`) REFERENCES `task_run` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Timing and metadata info about background/quartz processes';
--;;
CREATE TABLE `task_run` (
  `id` int NOT NULL AUTO_INCREMENT,
  `run_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of run: subscription, alert, sync, fingerprint',
  `entity_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of associated entity: database, card, dashboard',
  `entity_id` int NOT NULL COMMENT 'ID of associated entity',
  `started_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the run started',
  `ended_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When the run completed (null if still running)',
  `status` varchar(21) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Overall status: started, success, failed',
  `process_uuid` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unknown' COMMENT 'UUID of the Metabase instance that created this run',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Last heartbeat timestamp - updated periodically for running tasks',
  `notification_id` int DEFAULT NULL COMMENT 'ID of the notification that produced this run (null for non-notification runs, or runs predating this column)',
  PRIMARY KEY (`id`),
  KEY `idx_task_run_type_entity` (`run_type`,`entity_type`,`entity_id`),
  KEY `idx_task_run_started_at` (`started_at` DESC),
  KEY `idx_task_run_notification_id_started_at` (`notification_id`,`started_at` DESC),
  KEY `idx_task_run_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Groups related tasks from a single operation (subscription, alert, sync, fingerprint)';
--;;
CREATE TABLE `tenant` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'the ID of the tenant',
  `name` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'the unique name of the tenant',
  `slug` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'the slugified version of this tenant''s name',
  `is_active` bit(1) NOT NULL DEFAULT b'1' COMMENT 'Whether the tenant is active or not',
  `updated_at` timestamp(6) NOT NULL COMMENT 'The timestamp of when the tenant was updated',
  `created_at` timestamp(6) NOT NULL COMMENT 'The timestamp of when the tenant was created',
  `attributes` longtext COLLATE utf8mb4_unicode_ci COMMENT 'JSON object containing custom tenant attributes',
  `tenant_collection_id` int NOT NULL COMMENT 'The ID of the collection',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tenants (collections of external users). A user can be in exactly zero or one tenants.\n';
--;;
CREATE TABLE `timeline` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of the timeline',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Optional description of the timeline',
  `icon` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `collection_id` int DEFAULT NULL COMMENT 'ID of the collection containing the timeline',
  `archived` bit(1) NOT NULL DEFAULT b'0',
  `creator_id` int NOT NULL COMMENT 'ID of the user who created the timeline',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the timeline was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the timeline was updated',
  `default` bit(1) NOT NULL DEFAULT b'0',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `fk_timeline_creator_id` (`creator_id`),
  KEY `idx_timeline_collection_id` (`collection_id`),
  CONSTRAINT `fk_timeline_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_timeline_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Timeline table to organize events';
--;;
CREATE TABLE `timeline_event` (
  `id` int NOT NULL AUTO_INCREMENT,
  `timeline_id` int NOT NULL COMMENT 'ID of the timeline containing the event',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of the event',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Optional markdown description of the event',
  `timestamp` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the event happened',
  `time_matters` bit(1) NOT NULL,
  `timezone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Timezone to display the underlying UTC timestamp in for the client',
  `icon` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `archived` bit(1) NOT NULL DEFAULT b'0',
  `creator_id` int NOT NULL COMMENT 'ID of the user who created the event',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the event was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the event was modified',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_timeline_event_entity_id` (`entity_id`),
  KEY `fk_event_creator_id` (`creator_id`),
  KEY `idx_timeline_event_timeline_id` (`timeline_id`),
  KEY `idx_timeline_event_timeline_id_timestamp` (`timeline_id`,`timestamp`),
  CONSTRAINT `fk_event_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_events_timeline_id` FOREIGN KEY (`timeline_id`) REFERENCES `timeline` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Events table';
--;;
CREATE TABLE `transform` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `name` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'the description of the transform',
  `source` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON of source',
  `target` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON of target',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the transform was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp of when the transform was updated',
  `source_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `creator_id` int NOT NULL DEFAULT '13371338' COMMENT 'User who created this transform',
  `source_database_id` int DEFAULT NULL,
  `collection_id` int DEFAULT NULL COMMENT 'The collection the transform is in',
  `owner_user_id` int DEFAULT NULL COMMENT 'The user ID of the owner of this transform (can be different from creator)',
  `owner_email` longtext COLLATE utf8mb4_unicode_ci COMMENT 'An optional email address of the owner of this transform (for external owners), exclusive with owner_user_id',
  `target_db_id` int DEFAULT NULL COMMENT 'Target database ID for the transform output',
  `last_checkpoint_value` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Serialized checkpoint watermark value for incremental transforms, temporal as ISO8601',
  `target_table_id` int DEFAULT NULL COMMENT 'FK to metabase_table for the transform''s target table',
  `table_dependencies` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Precomputed table dependencies (JSON) used for execution ordering and cycle detection. Null means not yet computed.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_transform_creator_id` (`creator_id`),
  KEY `idx_transform_source_database_id` (`source_database_id`),
  KEY `idx_transform_collection_id` (`collection_id`),
  KEY `idx_transform_owner_user_id` (`owner_user_id`),
  KEY `idx_transform_target_db_id` (`target_db_id`),
  KEY `idx_transform_target_table_id` (`target_table_id`),
  CONSTRAINT `fk_tranform_source_database_id` FOREIGN KEY (`source_database_id`) REFERENCES `metabase_database` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_transform_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`),
  CONSTRAINT `fk_transform_owner_user_id` FOREIGN KEY (`owner_user_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_transform_ref_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_transform_target_db_id` FOREIGN KEY (`target_db_id`) REFERENCES `metabase_database` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_transform_target_table_id` FOREIGN KEY (`target_table_id`) REFERENCES `metabase_table` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='The main table for Transform entities';
--;;
CREATE TABLE `transform_dag_run` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `source_transform_id` int DEFAULT NULL COMMENT 'The seed transform the DAG reprocess was triggered from (null if it was later deleted)',
  `source_transform_name` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Name of the seed transform at run start, preserved after its deletion',
  `source_transform_entity_id` char(21) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'entity_id of the seed transform at run start, for potential reconnection when it is recreated',
  `direction` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'DAG traversal direction (upstream/downstream) that selected the transforms to run',
  `transform_count` int DEFAULT NULL COMMENT 'Number of transforms the run''s plan selected to run, for display in run listings',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Current status of the run (started, succeeded, failed, timeout, canceled)',
  `is_active` bit(1) DEFAULT NULL COMMENT 'True only for currently running DAG runs, null for the others',
  `start_time` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the DAG run started',
  `end_time` timestamp(6) NULL DEFAULT NULL COMMENT 'When the DAG run completed (null if still running)',
  `message` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Human-readable message about the run; may contain the error message when the run failed',
  `user_id` int DEFAULT NULL COMMENT 'The user who triggered the DAG run (null if the user was later deleted)',
  `last_heartbeat` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Heartbeat timestamp stamped periodically while the run executes; a stale value means the owning process died',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp this DAG run was created.',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp this DAG run was last updated.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_active_transform_dag_run` (`source_transform_id`,`is_active`),
  KEY `idx_transform_dag_run_source_transform_id` (`source_transform_id`),
  KEY `idx_transform_dag_run_user_id` (`user_id`),
  KEY `idx_transform_dag_run_active_runs` (`is_active`,`last_heartbeat`),
  CONSTRAINT `fk_transform_dag_run_source_transform_id` FOREIGN KEY (`source_transform_id`) REFERENCES `transform` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_transform_dag_run_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tracks manual DAG-reprocess runs (reprocessing a transform''s upstream/downstream dependency DAG)';
--;;
CREATE TABLE `transform_job` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `name` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The name of the transform job.',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'A description of the transform job.',
  `schedule` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Cron expression for job schedule',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp this transform job was created.',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp this transform job was last updated.',
  `built_in_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Type of the built-in transform job: hourly, daily, weekly, monthly.',
  `ui_display_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cron/raw' COMMENT 'The display type of the schedule, used for the UI only; "cron/raw" or "cron/builder".',
  `active` bit(1) NOT NULL DEFAULT b'1' COMMENT 'Whether the job is active. Inactive jobs do not run on schedule.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Jobs that execute transforms based on tags';
--;;
