CREATE TABLE `transform_test` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `transform_id` int NOT NULL COMMENT 'The transform under test',
  `creator_id` int NOT NULL COMMENT 'The user who created the test suite',
  `name` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The name of the test suite',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT 'A description of the test suite',
  `inputs` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON array of the input tables replaced with fixture data',
  `expectations` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON array of the expectations checked against the transform output',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp this test suite was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'The timestamp this test suite was last updated',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_transform_test_transform_id` (`transform_id`),
  KEY `idx_transform_test_creator_id` (`creator_id`),
  CONSTRAINT `fk_transform_test_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_transform_test_transform_id` FOREIGN KEY (`transform_id`) REFERENCES `transform` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A test for a transform, with fixture inputs and expectations on its output';
--;;
CREATE TABLE `transform_test_run` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `transform_test_id` int DEFAULT NULL COMMENT 'The transform test that was run',
  `initiated_by` int DEFAULT NULL COMMENT 'ID of the user who initiated the transform test run',
  `start_time` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When the transform test run started',
  `end_time` timestamp(6) NULL DEFAULT NULL COMMENT 'When the transform test run completed; null while it is running',
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Current status of the transform test run (started, passed, failed, error, or timeout)',
  `last_heartbeat` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Heartbeat stamped while the run executes; a stale value means the owning process died',
  PRIMARY KEY (`id`),
  KEY `idx_transform_test_run_transform_test_id` (`transform_test_id`),
  KEY `idx_transform_test_run_active_runs` (`status`,`last_heartbeat`),
  KEY `idx_transform_test_run_initiated_by` (`initiated_by`),
  CONSTRAINT `fk_transform_test_run_initiated_by` FOREIGN KEY (`initiated_by`) REFERENCES `core_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_transform_test_run_transform_test_id` FOREIGN KEY (`transform_test_id`) REFERENCES `transform_test` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='An execution of a transform test and its outcome';
--;;
CREATE TABLE `transform_transform_tag` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `transform_id` int NOT NULL COMMENT 'The id of the transform.',
  `tag_id` int NOT NULL COMMENT 'The id of the tag.',
  `entity_id` char(21) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `position` int NOT NULL COMMENT 'The relative UI ordering of this tag on the transform',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_transform_tag` (`transform_id`,`tag_id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `fk_transform_transform_tag_tag_id` (`tag_id`),
  CONSTRAINT `fk_transform_transform_tag_tag_id` FOREIGN KEY (`tag_id`) REFERENCES `transform_tag` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_transform_transform_tag_transform_id` FOREIGN KEY (`transform_id`) REFERENCES `transform` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Join table for transforms and tags';
--;;
CREATE TABLE `user_key_value` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT 'The ID of the user this KV-pair is for',
  `namespace` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The namespace for this KV, e.g. "dashboard-filters" or "nobody-knows"',
  `key` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The key',
  `value` longtext COLLATE utf8mb4_unicode_ci COMMENT 'The value, serialized JSON',
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When this row was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'When this row was last updated',
  `expires_at` timestamp(6) NULL DEFAULT NULL COMMENT 'If set, when this row expires',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_key_value_user_id_namespace_key` (`user_id`,`namespace`,`key`),
  CONSTRAINT `fk_user_key_value_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A simple key value store for each user.';
--;;
CREATE TABLE `user_parameter_value` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT 'ID of the User who has set the parameter value',
  `parameter_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The parameter ID',
  `value` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Value of the parameter',
  `dashboard_id` int DEFAULT NULL COMMENT 'The ID of the dashboard',
  PRIMARY KEY (`id`),
  KEY `idx_user_parameter_value_user_id` (`user_id`),
  KEY `idx_user_parameter_value_dashboard_id` (`dashboard_id`),
  KEY `idx_user_parameter_value_user_id_dashboard_id_parameter_id` (`user_id`,`dashboard_id`,`parameter_id`),
  CONSTRAINT `fk_user_parameter_value_dashboard_id` FOREIGN KEY (`dashboard_id`) REFERENCES `report_dashboard` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_user_parameter_value_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table holding last set value of a parameter per user';
--;;
CREATE TABLE `view_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `model` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `model_id` int NOT NULL,
  `timestamp` timestamp(6) NULL DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `has_access` bit(1) DEFAULT NULL,
  `context` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The context of the view, can be collection, question, or dashboard. Only for cards.',
  `embedding_client` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Used by the embedding team to track SDK usage',
  `embedding_sdk_version` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `auth_method` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Authentication method used (e.g. jwt, saml, api-key, public, guest, etc.)',
  `tenant_id` int DEFAULT NULL COMMENT 'Tenant ID of the user who generated this view',
  `embedding_hostname` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Hostname from Origin header, PII',
  `embedding_path` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path from Referer header (query params stripped), PII',
  `user_agent` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-Agent header, PII',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client IP address, PII',
  `sanitized_user_agent` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Human-friendly parsed User-Agent (e.g. Browser (Chrome/Windows)), PII',
  `embedding_route` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'API route surface (e.g. public, guest-embed, metabot, agent-api)',
  `metabase_version` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Metabase server version tag at time of insert',
  `embedding_client_identifier` varchar(254) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Identifier of the concrete embedding client (e.g. the data-app name) from the X-Metabase-Client-Identifier header',
  PRIMARY KEY (`id`),
  KEY `idx_view_log_user_id` (`user_id`),
  KEY `idx_view_log_model_id` (`model_id`),
  KEY `idx_view_log_timestamp` (`timestamp`),
  KEY `idx_view_log_tenant_id` (`tenant_id`),
  KEY `idx_view_log_entity_qualified_id` ((concat(`model`,_utf8mb4'_',`model_id`))),
  CONSTRAINT `fk_view_log_ref_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE OR REPLACE SQL SECURITY DEFINER VIEW `v_agent_api_calls` AS select `t`.`id` AS `call_id`,`t`.`created_at` AS `created_at`,`t`.`operation` AS `operation`,`t`.`status` AS `status`,`t`.`error_message` AS `error_message`,`t`.`duration_ms` AS `duration_ms`,`t`.`user_id` AS `user_id`,coalesce(concat(`u`.`first_name`,' ',`u`.`last_name`),`u`.`email`) AS `user_display_name`,(select `pg`.`name` from (`permissions_group_membership` `pgm` join `permissions_group` `pg` on((`pg`.`id` = `pgm`.`group_id`))) where ((`pgm`.`user_id` = `t`.`user_id`) and (`pg`.`id` <> 1)) order by `pg`.`name` limit 1) AS `group_name`,`t`.`client_name` AS `client_name`,(case `t`.`client_name` when 'metabase-cli' then 'Metabase CLI' when 'other' then 'Other' else `t`.`client_name` end) AS `client_display_name`,`t`.`tenant_id` AS `tenant_id`,`tn`.`name` AS `tenant_name`,`t`.`ip_address` AS `ip_address` from ((`agent_api_call_log` `t` left join `core_user` `u` on((`u`.`id` = `t`.`user_id`))) left join `tenant` `tn` on((`tn`.`id` = `t`.`tenant_id`)));
--;;
CREATE OR REPLACE SQL SECURITY DEFINER VIEW `v_ai_usage_log` AS select `a`.`id` AS `usage_log_id`,`a`.`created_at` AS `created_at`,`a`.`source` AS `source`,(case `a`.`source` when 'metabot_agent' then 'Metabot' when 'agent' then 'Metabot' when 'contextual_interestingness' then 'Research' when 'exploration' then 'Research' when 'document_generate_content' then 'Documents' when 'example_question_generation_batch' then 'Suggested Prompts' when 'conversation_title' then 'Conversation titles' when 'slack' then 'Slackbot' when 'slackbot' then 'Slackbot' when 'oss-sql-gen' then 'SQL' when 'sql-gen' then 'SQL' when 'unknown' then 'Unknown' else `a`.`source` end) AS `source_name`,`a`.`model` AS `model`,`a`.`profile_id` AS `profile_id`,`a`.`prompt_tokens` AS `prompt_tokens`,`a`.`completion_tokens` AS `completion_tokens`,`a`.`total_tokens` AS `total_tokens`,`a`.`conversation_id` AS `conversation_id`,`a`.`user_id` AS `user_id`,concat('user_',`a`.`user_id`) AS `user_qualified_id`,coalesce(concat(`u`.`first_name`,' ',`u`.`last_name`),`u`.`email`) AS `user_display_name`,(select `pg`.`name` from (`permissions_group_membership` `pgm` join `permissions_group` `pg` on((`pg`.`id` = `pgm`.`group_id`))) where ((`pgm`.`user_id` = `a`.`user_id`) and (`pg`.`id` <> 1)) order by `pg`.`name` limit 1) AS `group_name`,`c`.`ip_address` AS `ip_address`,`c`.`embedding_hostname` AS `embedding_hostname`,`c`.`embedding_path` AS `embedding_path`,`c`.`user_agent` AS `user_agent`,`c`.`sanitized_user_agent` AS `sanitized_user_agent`,`c`.`forked_from_conversation_id` AS `forked_from_conversation_id`,`a`.`tenant_id` AS `tenant_id`,`a`.`request_id` AS `request_id`,`a`.`cache_creation_tokens` AS `cache_creation_tokens`,`a`.`cache_read_tokens` AS `cache_read_tokens` from ((`ai_usage_log` `a` left join `core_user` `u` on((`u`.`id` = `a`.`user_id`))) left join `metabot_conversation` `c` on((`c`.`id` = `a`.`conversation_id`)));
--;;
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_alerts` AS with `parsed_cron` as (select `n`.`id` AS `id`,`ns`.`cron_schedule` AS `cron_schedule`,`ns`.`ui_display_type` AS `ui_display_type`,substring_index(substring_index(`ns`.`cron_schedule`,' ',2),' ',-(1)) AS `minutes`,substring_index(substring_index(`ns`.`cron_schedule`,' ',3),' ',-(1)) AS `hours`,substring_index(substring_index(`ns`.`cron_schedule`,' ',4),' ',-(1)) AS `day_of_month`,substring_index(substring_index(`ns`.`cron_schedule`,' ',6),' ',-(1)) AS `day_of_week` from (`notification` `n` join `notification_subscription` `ns` on((`n`.`id` = `ns`.`notification_id`))) where ((`n`.`payload_type` = 'notification/card') and (`ns`.`type` = 'notification-subscription/cron'))), `schedule_info` as (select `parsed_cron`.`id` AS `id`,(case when (`parsed_cron`.`ui_display_type` = 'cron/raw') then 'custom' when (regexp_like(`parsed_cron`.`minutes`,'^\\*$') or regexp_like(`parsed_cron`.`minutes`,'^[0-9]+/[0-9]+$')) then 'by the minute' when ((`parsed_cron`.`day_of_month` <> '*') and ((`parsed_cron`.`day_of_week` = '?') or regexp_like(`parsed_cron`.`day_of_week`,'^[0-9]#1$') or regexp_like(`parsed_cron`.`day_of_week`,'^[0-9]L$'))) then 'monthly' when ((`parsed_cron`.`day_of_week` <> '?') and (`parsed_cron`.`day_of_week` <> '*')) then 'weekly' when (`parsed_cron`.`hours` <> '*') then 'daily' else 'hourly' end) AS `schedule_type`,(case when regexp_like(`parsed_cron`.`day_of_week`,'^1') then 'sun' when regexp_like(`parsed_cron`.`day_of_week`,'^2') then 'mon' when regexp_like(`parsed_cron`.`day_of_week`,'^3') then 'tue' when regexp_like(`parsed_cron`.`day_of_week`,'^4') then 'wed' when regexp_like(`parsed_cron`.`day_of_week`,'^5') then 'thu' when regexp_like(`parsed_cron`.`day_of_week`,'^6') then 'fri' when regexp_like(`parsed_cron`.`day_of_week`,'^7') then 'sat' else NULL end) AS `schedule_day`,(case when (`parsed_cron`.`hours` = '*') then NULL when regexp_like(`parsed_cron`.`hours`,'^[0-9]+$') then cast(`parsed_cron`.`hours` as signed) when regexp_like(`parsed_cron`.`hours`,'^([0-9]+)/[0-9]+$') then cast(substring_index(`parsed_cron`.`hours`,'/',1) as signed) else NULL end) AS `schedule_hour` from `parsed_cron`), `agg_recipients` as (select `nr`.`notification_handler_id` AS `notification_handler_id`,group_concat(`cu`.`email` separator ',') AS `recipients`,group_concat((case when (`nr`.`type` = 'notification-recipient/raw-value') then `nr`.`details` else NULL end) separator ',') AS `recipient_external` from (`notification_recipient` `nr` left join `core_user` `cu` on(((`nr`.`user_id` = `cu`.`id`) and (`nr`.`type` = 'notification-recipient/user')))) group by `nr`.`notification_handler_id`) select `n`.`id` AS `entity_id`,concat('notification_',`n`.`id`) AS `entity_qualified_id`,`n`.`created_at` AS `created_at`,`n`.`updated_at` AS `updated_at`,`n`.`creator_id` AS `creator_id`,`nc`.`card_id` AS `card_id`,concat('card_',`nc`.`card_id`) AS `card_qualified_id`,(case when (`nc`.`send_condition` = 'has_result') then 'rows' when (`nc`.`send_condition` in ('goal_above','goal_below')) then 'goal' end) AS `alert_condition`,`si`.`schedule_type` AS `schedule_type`,`si`.`schedule_day` AS `schedule_day`,`si`.`schedule_hour` AS `schedule_hour`,(0 = `n`.`active`) AS `archived`,`nh`.`channel_type` AS `recipient_type`,`ar`.`recipients` AS `recipients`,`ar`.`recipient_external` AS `recipient_external` from ((((`notification` `n` join `notification_card` `nc` on((`n`.`payload_id` = `nc`.`id`))) join `schedule_info` `si` on((`n`.`id` = `si`.`id`))) left join `notification_handler` `nh` on((`n`.`id` = `nh`.`notification_id`))) left join `agg_recipients` `ar` on((`nh`.`id` = `ar`.`notification_handler_id`))) where (`n`.`payload_type` = 'notification/card');
--;;
CREATE OR REPLACE SQL SECURITY DEFINER VIEW `v_api_key_usage` AS select `t`.`id` AS `log_id`,`t`.`occurred_at` AS `occurred_at`,`t`.`route_template` AS `route_template`,`t`.`http_method` AS `http_method`,`t`.`status` AS `status`,`t`.`duration_ms` AS `duration_ms`,`t`.`api_key_id` AS `api_key_id`,`ak`.`name` AS `api_key_name`,`t`.`user_id` AS `actor_user_id`,`t`.`created_by_id` AS `creator_id`,coalesce(concat(`creator`.`first_name`,' ',`creator`.`last_name`),`creator`.`email`) AS `creator_display_name`,(select `pg`.`name` from (`permissions_group_membership` `pgm` join `permissions_group` `pg` on((`pg`.`id` = `pgm`.`group_id`))) where (`pgm`.`user_id` = `ak`.`user_id`) order by (case when (`pg`.`id` = 1) then 1 else 0 end),`pg`.`name` limit 1) AS `group_name`,`t`.`client_name` AS `client_name`,(case `t`.`client_name` when 'metabase-cli' then 'Metabase CLI' when 'curl' then 'curl' when 'postman' then 'Postman' when 'python-requests' then 'Python' when 'r' then 'R' when 'node' then 'Node.js' when 'other' then 'Other' else `t`.`client_name` end) AS `client_display_name`,`t`.`embedding_client` AS `embedding_client`,`t`.`embedding_hostname` AS `embedding_hostname`,`t`.`ip_address` AS `ip_address`,`t`.`user_agent` AS `user_agent` from ((`api_key_usage_log` `t` left join `api_key` `ak` on((`ak`.`id` = `t`.`api_key_id`))) left join `core_user` `creator` on((`creator`.`id` = `t`.`created_by_id`)));
--;;
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_audit_log` AS select `audit_log`.`id` AS `id`,(case when (`audit_log`.`topic` = 'card-create') then 'card-create' when (`audit_log`.`topic` = 'card-delete') then 'card-delete' when (`audit_log`.`topic` = 'card-update') then 'card-update' when (`audit_log`.`topic` = 'pulse-create') then 'subscription-create' when (`audit_log`.`topic` = 'pulse-delete') then 'subscription-delete' else `audit_log`.`topic` end) AS `topic`,`audit_log`.`timestamp` AS `timestamp`,NULL AS `end_timestamp`,coalesce(`audit_log`.`user_id`,0) AS `user_id`,lower(`audit_log`.`model`) AS `entity_type`,`audit_log`.`model_id` AS `entity_id`,(case when (`audit_log`.`model` = 'Dataset') then concat('card_',`audit_log`.`model_id`) when (`audit_log`.`model_id` is null) then NULL else concat(lower(`audit_log`.`model`),'_',`audit_log`.`model_id`) end) AS `entity_qualified_id`,`audit_log`.`details` AS `details` from `audit_log` where (`audit_log`.`topic` not in ('card-read','card-query','dashboard-read','dashboard-query'));
--;;
