`.`collection_id` AS `collection_id`,`report_card`.`made_public_by_id` AS `made_public_by_user`,`report_card`.`enable_embedding` AS `is_embedding_enabled`,(case when `moderation`.`is_verified` then true else false end) AS `is_verified`,`report_card`.`archived` AS `archived`,NULL AS `action_type`,NULL AS `action_model_id`,NULL AS `collection_is_official`,NULL AS `collection_is_personal`,`report_card`.`display` AS `question_viz_type`,concat('database_',`report_card`.`database_id`) AS `question_database_id`,(case when (`report_card`.`query_type` = 'native') then true else false end) AS `question_is_native`,NULL AS `event_timestamp` from (`report_card` left join (select concat(`moderation_review`.`moderated_item_type`,'_',`moderation_review`.`moderated_item_id`) AS `entity_qualified_id`,(case when (`moderation_review`.`status` = 'verified') then true else false end) AS `is_verified` from `moderation_review` where (0 <> `moderation_review`.`most_recent`)) `moderation` on((concat('card_',`report_card`.`id`) = `moderation`.`entity_qualified_id`))) union select `report_dashboard`.`id` AS `entity_id`,concat('dashboard_',`report_dashboard`.`id`) AS `entity_qualified_id`,'dashboard' AS `entity_type`,`report_dashboard`.`created_at` AS `created_at`,`report_dashboard`.`updated_at` AS `updated_at`,`report_dashboard`.`creator_id` AS `creator_id`,`report_dashboard`.`name` AS `name`,`report_dashboard`.`description` AS `description`,`report_dashboard`.`collection_id` AS `collection_id`,`report_dashboard`.`made_public_by_id` AS `made_public_by_user`,`report_dashboard`.`enable_embedding` AS `is_embedding_enabled`,(case when `moderation`.`is_verified` then true else false end) AS `is_verified`,`report_dashboard`.`archived` AS `archived`,NULL AS `action_type`,NULL AS `action_model_id`,NULL AS `collection_is_official`,NULL AS `collection_is_personal`,NULL AS `question_viz_type`,NULL AS `question_database_id`,NULL AS `question_is_native`,NULL AS `event_timestamp` from (`report_dashboard` left join (select concat(`moderation_review`.`moderated_item_type`,'_',`moderation_review`.`moderated_item_id`) AS `entity_qualified_id`,(case when (`moderation_review`.`status` = 'verified') then true else false end) AS `is_verified` from `moderation_review` where (0 <> `moderation_review`.`most_recent`)) `moderation` on((concat('dashboard_',`report_dashboard`.`id`) = `moderation`.`entity_qualified_id`))) union select `document`.`id` AS `entity_id`,concat('document_',`document`.`id`) AS `entity_qualified_id`,'document' AS `entity_type`,`document`.`created_at` AS `created_at`,`document`.`updated_at` AS `updated_at`,`document`.`creator_id` AS `creator_id`,`document`.`name` AS `name`,NULL AS `description`,`document`.`collection_id` AS `collection_id`,NULL AS `made_public_by_user`,NULL AS `is_embedding_enabled`,NULL AS `is_verified`,`document`.`archived` AS `archived`,NULL AS `action_type`,NULL AS `action_model_id`,NULL AS `collection_is_official`,NULL AS `collection_is_personal`,NULL AS `question_viz_type`,NULL AS `question_database_id`,NULL AS `question_is_native`,NULL AS `event_timestamp` from `document` where (`document`.`exploration_id` is null) union select `exploration`.`id` AS `entity_id`,concat('exploration_',`exploration`.`id`) AS `entity_qualified_id`,'exploration' AS `entity_type`,`exploration`.`created_at` AS `created_at`,`exploration`.`updated_at` AS `updated_at`,`exploration`.`creator_id` AS `creator_id`,`exploration`.`name` AS `name`,`exploration`.`description` AS `description`,`exploration`.`collection_id` AS `collection_id`,NULL AS `made_public_by_user`,NULL AS `is_embedding_enabled`,NULL AS `is_verified`,`exploration`.`archived` AS `archived`,NULL AS `action_type`,NULL AS `action_model_id`,NULL AS `collection_is_official`,NULL AS `collection_is_personal`,NULL AS `question_viz_type`,NULL AS `question_database_id`,NULL AS `question_is_native`,NULL AS `event_timestamp` from `exploration` union select `event`.`id` AS `entity_id`,concat('event_',`event`.`id`) AS `entity_qualified_id`,'event' AS `entity_type`,`event`.`created_at` AS `created_at`,`event`.`updated_at` AS `updated_at`,`event`.`creator_id` AS `creator_id`,`event`.`name` AS `name`,`event`.`description` AS `description`,`timeline`.`collection_id` AS `collection_id`,NULL AS `made_public_by_user`,NULL AS `is_embedding_enabled`,NULL AS `is_verified`,`event`.`archived` AS `archived`,NULL AS `action_type`,NULL AS `action_model_id`,NULL AS `collection_is_official`,NULL AS `collection_is_personal`,NULL AS `question_viz_type`,NULL AS `question_database_id`,NULL AS `question_is_native`,`event`.`timestamp` AS `event_timestamp` from (`timeline_event` `event` left join `timeline` on((`event`.`timeline_id` = `timeline`.`id`))) union select `transform`.`id` AS `entity_id`,concat('transform_',`transform`.`id`) AS `entity_qualified_id`,'transform' AS `entity_type`,`transform`.`created_at` AS `created_at`,`transform`.`updated_at` AS `updated_at`,`transform`.`creator_id` AS `creator_id`,`transform`.`name` AS `name`,`transform`.`description` AS `description`,NULL AS `collection_id`,NULL AS `made_public_by_user`,NULL AS `is_embedding_enabled`,NULL AS `is_verified`,false AS `archived`,NULL AS `action_type`,NULL AS `action_model_id`,NULL AS `collection_is_official`,NULL AS `collection_is_personal`,NULL AS `question_viz_type`,NULL AS `question_database_id`,NULL AS `question_is_native`,NULL AS `event_timestamp` from `transform` union select `glossary`.`id` AS `entity_id`,concat('glossary_',`glossary`.`id`) AS `entity_qualified_id`,'glossary' AS `entity_type`,`glossary`.`created_at` AS `created_at`,`glossary`.`updated_at` AS `updated_at`,`glossary`.`creator_id` AS `creator_id`,`glossary`.`term` AS `name`,`glossary`.`definition` AS `description`,NULL AS `collection_id`,NULL AS `made_public_by_user`,NULL AS `is_embedding_enabled`,NULL AS `is_verified`,false AS `archived`,NULL AS `action_type`,NULL AS `action_model_id`,NULL AS `collection_is_official`,NULL AS `collection_is_personal`,N