CREATE OR REPLACE SQL SECURITY DEFINER VIEW `v_databases` AS select `metabase_database`.`id` AS `entity_id`,concat('database_',`metabase_database`.`id`) AS `entity_qualified_id`,`metabase_database`.`created_at` AS `created_at`,`metabase_database`.`updated_at` AS `updated_at`,`metabase_database`.`name` AS `name`,`metabase_database`.`description` AS `description`,`metabase_database`.`engine` AS `database_type`,`metabase_database`.`metadata_sync_schedule` AS `metadata_sync_schedule`,`metabase_database`.`cache_field_values_schedule` AS `cache_field_values_schedule`,`metabase_database`.`timezone` AS `timezone`,`metabase_database`.`is_on_demand` AS `is_on_demand`,`metabase_database`.`auto_run_queries` AS `auto_run_queries`,`metabase_database`.`cache_ttl` AS `cache_ttl`,`metabase_database`.`creator_id` AS `creator_id`,`metabase_database`.`dbms_version` AS `db_version` from `metabase_database` where (`metabase_database`.`id` <> 13371337);
