CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_fields` AS select `f`.`id` AS `entity_id`,concat('field_',`f`.`id`) AS `entity_qualified_id`,`f`.`created_at` AS `created_at`,`f`.`updated_at` AS `updated_at`,`f`.`name` AS `name`,coalesce(`u`.`display_name`,`f`.`display_name`) AS `display_name`,(case when `u`.`description_set` then `u`.`description` else `f`.`description` end) AS `description`,`f`.`base_type` AS `base_type`,coalesce(`u`.`visibility_type`,`f`.`visibility_type`) AS `visibility_type`,(case when `u`.`fk_target_field_id_set` then `u`.`fk_target_field_id` else `f`.`fk_target_field_id` end) AS `fk_target_field_id`,coalesce(`u`.`has_field_values`,`f`.`has_field_values`) AS `has_field_values`,`f`.`active` AS `active`,`f`.`table_id` AS `table_id` from (`metabase_field` `f` left join `metabase_field_user_settings` `u` on((`u`.`field_id` = `f`.`id`)));
