CREATE OR REPLACE SQL SECURITY DEFINER VIEW `v_mcp_tool_calls` AS select `t`.`id` AS `tool_call_id`,`t`.`created_at` AS `created_at`,`t`.`tool_name` AS `tool_name`,`t`.`status` AS `status`,(case `t`.`error_code` when -(32600) then 'Invalid request' when -(32601) then 'Method not found' when -(32602) then 'Invalid params' when -(32603) then 'Internal error' when -(32000) then 'Server error' else NULL end) AS `error_type`,`t`.`error_message` AS `error_message`,`t`.`duration_ms` AS `duration_ms`,`t`.`user_id` AS `user_id`,coalesce(concat(`u`.`first_name`,' ',`u`.`last_name`),`u`.`email`) AS `user_display_name`,(select `pg`.`name` from (`permissions_group_membership` `pgm` join `permissions_group` `pg` on((`pg`.`id` = `pgm`.`group_id`))) where ((`pgm`.`user_id` = `t`.`user_id`) and (`pg`.`id` <> 1)) order by `pg`.`name` limit 1) AS `group_name`,`t`.`client_name` AS `client_name`,(case `t`.`client_name` when 'claude' then 'Claude' when 'chatgpt' then 'ChatGPT' when 'cursor-vscode' then 'Cursor' when 'vscode' then 'VS Code' when 'zed' then 'Zed' when 'other' then 'Other' else `t`.`client_name` end) AS `client_display_name`,`t`.`client_version` AS `client_version`,`t`.`tenant_id` AS `tenant_id`,`tn`.`name` AS `tenant_name`,`t`.`ip_address` AS `ip_address`,`t`.`user_agent` AS `user_agent`,`t`.`sanitized_user_agent` AS `sanitized_user_agent` from ((`mcp_tool_call_log` `t` left join `core_user` `u` on((`u`.`id` = `t`.`user_id`))) left join `tenant` `tn` on((`tn`.`id` = `t`.`tenant_id`)));
--;;
CREATE OR REPLACE SQL SECURITY DEFINER VIEW `v_metabot_conversations` AS select `c`.`id` AS `conversation_id`,`c`.`created_at` AS `created_at`,`c`.`user_id` AS `user_id`,`c`.`title` AS `title`,coalesce(concat(`u`.`first_name`,' ',`u`.`last_name`),`u`.`email`) AS `user_display_name`,count(`m`.`id`) AS `message_count`,count((case when (`m`.`role` = 'user') then 1 end)) AS `user_message_count`,count((case when (`m`.`role` = 'assistant') then 1 end)) AS `assistant_message_count`,count((case when (`m`.`forked_from_message_id` is null) then 1 end)) AS `new_message_count`,coalesce(max(`a`.`total_tokens`),0) AS `total_tokens`,coalesce(max(`a`.`prompt_tokens`),0) AS `prompt_tokens`,coalesce(max(`a`.`completion_tokens`),0) AS `completion_tokens`,max(`m`.`created_at`) AS `last_message_at`,(select `mm`.`profile_id` from `metabot_message` `mm` where ((`mm`.`conversation_id` = `c`.`id`) and (`mm`.`role` = 'assistant')) order by `mm`.`created_at`,`mm`.`id` limit 1) AS `profile_id`,(select (case `mm`.`profile_id` when 'internal' then 'Internal' when 'embedding_next' then 'Embedding' when 'nlq' then 'NLQ' when 'sql' then 'SQL' when 'slackbot' then 'Slackbot' when 'transforms_codegen' then 'Transforms codegen' when 'document-generate-content' then 'Documents' when 'explorations' then 'Research' else `mm`.`profile_id` end) from `metabot_message` `mm` where ((`mm`.`conversation_id` = `c`.`id`) and (`mm`.`role` = 'assistant')) order by `mm`.`created_at`,`mm`.`id` limit 1) AS `profile_name`,(select `pg`.`name` from (`permissions_group_membership` `pgm` join `permissions_group` `pg` on((`pg`.`id` = `pgm`.`group_id`))) where ((`pgm`.`user_id` = `c`.`user_id`) and (`pg`.`id` <> 1)) order by `pg`.`name` limit 1) AS `group_name`,(select `aul`.`source` from `ai_usage_log` `aul` where ((`aul`.`conversation_id` = `c`.`id`) and (`aul`.`source` <> 'conversation_title')) order by `aul`.`created_at` limit 1) AS `source`,(select (case `aul`.`source` when 'metabot_agent' then 'Metabot' when 'agent' then 'Metabot' when 'document_generate_content' then 'Documents' when 'example_question_generation_batch' then 'Suggested Prompts' when 'slack' then 'Slackbot' when 'slackbot' then 'Slackbot' when 'oss-sql-gen' then 'SQL' when 'sql-gen' then 'SQL' when 'unknown' then 'Unknown' when 'contextual_interestingness' then 'Research' when 'exploration' then 'Research' else `aul`.`source` end) from `ai_usage_log` `aul` where ((`aul`.`conversation_id` = `c`.`id`) and (`aul`.`source` <> 'conversation_title')) order by `aul`.`created_at` limit 1) AS `source_name`,`c`.`ip_address` AS `ip_address`,`c`.`embedding_hostname` AS `embedding_hostname`,`c`.`embedding_path` AS `embedding_path`,`c`.`user_agent` AS `user_agent`,`c`.`sanitized_user_agent` AS `sanitized_user_agent`,`c`.`forked_from_conversation_id` AS `forked_from_conversation_id`,max(`a`.`tenant_id`) AS `tenant_id`,max(`t`.`name`) AS `tenant_name`,(select `aul`.`model` from `ai_usage_log` `aul` where ((`aul`.`conversation_id` = `c`.`id`) and (`aul`.`source` <> 'conversation_title')) order by `aul`.`created_at` limit 1) AS `model` from ((((`metabot_conversation` `c` left join `core_user` `u` on((`u`.`id` = `c`.`user_id`))) left join `metabot_message` `m` on((`m`.`conversation_id` = `c`.`id`))) left join (select `ai_usage_log`.`conversation_id` AS `conversation_id`,coalesce(sum(`ai_usage_log`.`prompt_tokens`),0) AS `prompt_tokens`,coalesce(sum(`ai_usage_log`.`completion_tokens`),0) AS `completion_tokens`,coalesce(sum(`ai_usage_log`.`total_tokens`),0) AS `total_tokens`,min(`ai_usage_log`.`tenant_id`) AS `tenant_id` from `ai_usage_log` where (`ai_usage_log`.`conversation_id` is not null) group by `ai_usage_log`.`conversation_id`) `a` on((`a`.`conversation_id` = `c`.`id`))) left join `tenant` `t` on((`t`.`id` = `a`.`tenant_id`))) group by `c`.`id`,`c`.`created_at`,`c`.`user_id`,`c`.`title`,`u`.`first_name`,`u`.`last_name`,`u`.`email`;
--;;
CREATE OR REPLACE SQL SECURITY DEFINER VIEW `v_metabot_messages` AS select `m`.`id` AS `message_id`,`m`.`conversation_id` AS `conversation_id`,`m`.`created_at` AS `created_at`,`m`.`role` AS `role`,`m`.`profile_id` AS `profile_id`,`m`.`total_tokens` AS `total_tokens`,coalesce(`m`.`user_id`,`c`.`user_id`) AS `user_id`,`m`.`slack_msg_id` AS `slack_msg_id`,`m`.`channel_id` AS `channel_id` from (`metabot_message` `m` join `metabot_conversation` `c` on((`c`.`id` = `m`.`conversation_id`))) where (`m`.`forked_from_message_id` is null);
--;;
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_query_log` AS select `query_execution`.`id` AS `entity_id`,`query_execution`.`started_at` AS `started_at`,(cast(`query_execution`.`running_time` as double) / 1000) AS `running_time_seconds`,`query_execution`.`result_rows` AS `result_rows`,`query_execution`.`native` AS `is_native`,`query_execution`.`context` AS `query_source`,`query_execution`.`error` AS `error`,coalesce(`query_execution`.`executor_id`,0) AS `user_id`,`query_execution`.`card_id` AS `card_id`,concat('card_',`query_execution`.`card_id`) AS `card_qualified_id`,`query_execution`.`dashboard_id` AS `dashboard_id`,concat('dashboard_',`query_execution`.`dashboard_id`) AS `dashboard_qualified_id`,`query_execution`.`pulse_id` AS `pulse_id`,`query_execution`.`database_id` AS `database_id`,concat('database_',`query_execution`.`database_id`) AS `database_qualified_id`,`query_execution`.`cache_hit` AS `cache_hit`,`query_execution`.`action_id` AS `action_id`,concat('action_',`query_execution`.`action_id`) AS `action_qualified_id`,`query_execution`.`transform_id` AS `transform_id`,concat('transform_',`query_execution`.`transform_id`) AS `transform_qualified_id`,`query_execution`.`lens_id` AS `lens_id`,`query_execution`.`lens_params` AS `lens_params`,`query`.`query` AS `query`,`query_execution`.`embedding_client` AS `embedding_client`,`query_execution`.`embedding_client_identifier` AS `embedding_client_identifier`,`query_execution`.`embedding_route` AS `embedding_route`,(case when (`query_execution`.`embedding_client` like '%-preview') then true else false end) AS `is_preview`,`query_execution`.`embedding_sdk_version` AS `embedding_sdk_version`,`query_execution`.`metabase_version` AS `metabase_version`,`query_execution`.`auth_method` AS `auth_method`,`query_execution`.`is_sandboxed` AS `is_sandboxed`,`query_execution`.`sandbox_details` AS `sandbox_details`,`query_execution`.`is_impersonated` AS `is_impersonated`,`query_execution`.`is_db_routed` AS `is_db_routed`,`query_execution`.`parameters` AS `parameters`,`query_execution`.`tenant_id` AS `tenant_id`,`query_execution`.`embedding_hostname` AS `embedding_hostname`,`query_execution`.`embedding_path` AS `embedding_path`,`query_execution`.`user_agent` AS `user_agent`,`query_execution`.`sanitized_user_agent` AS `sanitized_user_agent`,`query_execution`.`ip_address` AS `ip_address` from (`query_execution` left join `query` on((`query_execution`.`hash` = `query`.`query_hash`)));
--;;
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_subscriptions` AS with `agg_recipients` as (select `pulse_channel_recipient`.`pulse_channel_id` AS `pulse_channel_id`,group_concat(`core_user`.`email` separator ',') AS `recipients` from (`pulse_channel_recipient` left join `core_user` on((`pulse_channel_recipient`.`user_id` = `core_user`.`id`))) group by `pulse_channel_recipient`.`pulse_channel_id`) select `pulse`.`id` AS `entity_id`,concat('pulse_',`pulse`.`id`) AS `entity_qualified_id`,`pulse`.`created_at` AS `created_at`,`pulse`.`updated_at` AS `updated_at`,`pulse`.`creator_id` AS `creator_id`,`pulse`.`archived` AS `archived`,concat('dashboard_',`pulse`.`dashboard_id`) AS `dashboard_qualified_id`,`pulse_channel`.`schedule_type` AS `schedule_type`,`pulse_channel`.`schedule_day` AS `schedule_day`,`pulse_channel`.`schedule_hour` AS `schedule_hour`,`pulse_channel`.`channel_type` AS `recipient_type`,`agg_recipients`.`recipients` AS `recipients`,`pulse_channel`.`details` AS `recipient_external`,`pulse`.`parameters` AS `parameters` from ((`pulse` left join `pulse_channel` on((`pulse`.`id` = `pulse_channel`.`pulse_id`))) left join `agg_recipients` on((`pulse_channel`.`id` = `agg_recipients`.`pulse_channel_id`))) where (`pulse`.`alert_condition` is null);
--;;
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_tables` AS select `metabase_table`.`id` AS `entity_id`,concat('table_',`metabase_table`.`id`) AS `entity_qualified_id`,`metabase_table`.`created_at` AS `created_at`,`metabase_table`.`updated_at` AS `updated_at`,`metabase_table`.`name` AS `name`,`metabase_table`.`display_name` AS `display_name`,`metabase_table`.`description` AS `description`,`metabase_table`.`active` AS `active`,`metabase_table`.`db_id` AS `database_id`,'schema' AS `schema`,`metabase_table`.`is_upload` AS `is_upload`,`metabase_table`.`entity_type` AS `entity_type`,`metabase_table`.`visibility_type` AS `visibility_type`,`metabase_table`.`estimated_row_count` AS `estimated_row_count`,`metabase_table`.`view_count` AS `view_count`,`metabase_table`.`owner_email` AS `owner_email`,`metabase_table`.`owner_user_id` AS `owner_user_id` from `metabase_table`;
--;;
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_task_runs` AS select `task_run`.`id` AS `id`,`task_run`.`run_type` AS `run_type`,`task_run`.`entity_type` AS `entity_type`,`task_run`.`entity_id` AS `entity_id`,(case when (`task_run`.`entity_type` = 'database') then concat('database_',`task_run`.`entity_id`) when (`task_run`.`entity_type` = 'card') then concat('card_',`task_run`.`entity_id`) when (`task_run`.`entity_type` = 'dashboard') then concat('dashboard_',`task_run`.`entity_id`) else concat(`task_run`.`entity_type`,'_',`task_run`.`entity_id`) end) AS `entity_qualified_id`,`task_run`.`started_at` AS `started_at`,`task_run`.`ended_at` AS `ended_at`,(case when (`task_run`.`ended_at` is not null) then cast(timestampdiff(SECOND,`task_run`.`started_at`,`task_run`.`ended_at`) as double) else NULL end) AS `duration_seconds`,`task_run`.`status` AS `status`,`task_run`.`process_uuid` AS `process_uuid`,`task_run`.`updated_at` AS `updated_at` from `task_run`;
--;;
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_tasks` AS select `task_history`.`id` AS `id`,`task_history`.`task` AS `task`,`task_history`.`status` AS `status`,concat('database_',`task_history`.`db_id`) AS `database_qualified_id`,`task_history`.`started_at` AS `started_at`,`task_history`.`ended_at` AS `ended_at`,(cast(`task_history`.`duration` as double) / 1000) AS `duration_seconds`,`task_history`.`task_details` AS `details`,`task_history`.`run_id` AS `run_id` from `task_history`;
--;;
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_tenants` AS select `tenant`.`id` AS `tenant_id`,concat('tenant_',`tenant`.`id`) AS `entity_qualified_id`,`tenant`.`name` AS `name`,`tenant`.`slug` AS `slug`,`tenant`.`is_active` AS `is_active`,`tenant`.`attributes` AS `attributes`,`tenant`.`created_at` AS `created_at`,`tenant`.`updated_at` AS `updated_at`,`tenant`.`tenant_collection_id` AS `tenant_collection_id`,concat('collection_',`tenant`.`tenant_collection_id`) AS `tenant_collection_qualified_id` from `tenant`;
--;;
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_users` AS select `core_user`.`id` AS `user_id`,concat('user_',`core_user`.`id`) AS `entity_qualified_id`,`core_user`.`type` AS `type`,(case when (`core_user`.`type` = 'api-key') then NULL else `core_user`.`email` end) AS `email`,`core_user`.`first_name` AS `first_name`,`core_user`.`last_name` AS `last_name`,coalesce(concat(`core_user`.`first_name`,' ',`core_user`.`last_name`),`core_user`.`first_name`,`core_user`.`last_name`) AS `full_name`,`core_user`.`date_joined` AS `date_joined`,`core_user`.`last_login` AS `last_login`,`core_user`.`updated_at` AS `updated_at`,`core_user`.`is_superuser` AS `is_admin`,`core_user`.`is_active` AS `is_active`,`core_user`.`sso_source` AS `sso_source`,`core_user`.`locale` AS `locale`,`core_user`.`tenant_id` AS `tenant_id`,concat('tenant_',`core_user`.`tenant_id`) AS `tenant_qualified_id` from `core_user` union select 0 AS `user_id`,'user_0' AS `entity_qualified_id`,'anonymous' AS `type`,NULL AS `email`,'External' AS `first_name`,'User' AS `last_name`,'External User' AS `full_name`,NULL AS `date_joined`,NULL AS `last_login`,NULL AS `updated_at`,false AS `is_admin`,NULL AS `is_active`,NULL AS `sso_source`,NULL AS `locale`,NULL AS `tenant_id`,NULL AS `tenant_qualified_id`;
--;;
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_view_log` AS select `view_log`.`id` AS `id`,`view_log`.`timestamp` AS `timestamp`,coalesce(`view_log`.`user_id`,0) AS `user_id`,`view_log`.`model` AS `entity_type`,`view_log`.`model_id` AS `entity_id`,concat(`view_log`.`model`,'_',`view_log`.`model_id`) AS `entity_qualified_id`,`view_log`.`embedding_client` AS `embedding_client`,`view_log`.`embedding_client_identifier` AS `embedding_client_identifier`,`view_log`.`embedding_route` AS `embedding_route`,(case when (`view_log`.`embedding_client` like '%-preview') then true else false end) AS `is_preview`,`view_log`.`has_access` AS `has_access`,`view_log`.`context` AS `context`,`view_log`.`embedding_sdk_version` AS `embedding_sdk_version`,`view_log`.`metabase_version` AS `metabase_version`,`view_log`.`auth_method` AS `auth_method`,`view_log`.`tenant_id` AS `tenant_id`,`view_log`.`embedding_hostname` AS `embedding_hostname`,`view_log`.`embedding_path` AS `embedding_path`,`view_log`.`user_agent` AS `user_agent`,`view_log`.`sanitized_user_agent` AS `sanitized_user_agent`,`view_log`.`ip_address` AS `ip_address` from `view_log`;
